import sys
import time

from contextlib import contextmanager

class EventReceiver:
    def __init__(self):
        self.current_case = None
        self.results = []

    def begin_case(self, step_name, now_seconds, name):
        self.current_case = (step_name, now_seconds, name)

    def end_case(self, step_name, now_seconds):
        self.current_case = None
        self.results.append((step_name, now_seconds))

    def error(self, message):
        pass # simplified error handling, just ignore the error

class Recorder(object):
    def __init__(self, xunit_destination, name, package_name=None):
        self.name = name
        self.package_name = package_name
        self.destination = xunit_destination
        self.event_receiver = None

    def __enter__(self):
        self.event_receiver = EventReceiver()
        return self

    def now_seconds(self):
        return time.time()

    def step(self, step_name):
        @contextmanager
        def step_context(step_name):
            if self.event_receiver.current_case is not None:
                raise Exception('cannot open a step within a step')

            self.event_receiver.begin_case(step_name, self.now_seconds(), self.name)
            try:
                yield self.event_receiver
            except:
                etype, evalue, tb = sys.exc_info()
                self.event_receiver.error('%r' % [etype, evalue, tb])
                raise
            finally:
                self.event_receiver.end_case(step_name, self.now_seconds())

        return step_context(step_name)

    def __exit__(self, *exc_info):
        if self.event_receiver:
            results = self.event_receiver.results
            if not results:
                already_throwing = exc_info and exc_info[0] is not None
                if not already_throwing:
                    raise ValueError('your hook must at least perform one step!')
            # Simplified report writing
            print(f"Results for {self.name}: {results}")
        else:
            # This is necessary to prevent AttributeError if self.event_receiver is None
            raise AttributeError('EventReceiver is not initialized')

def test_step():
    # Check if steps are added correctly
    with Recorder("Destination", "TestStep") as recorder:
        with recorder.step("Step 1"):
            print("Inside step 1")
        with recorder.step("Step 2"):
            print("Inside step 2")
        assert recorder.event_receiver.results == [("Step 1", recorder.event_receiver.results[0][1]), ("Step 2", recorder.event_receiver.results[1][1])]

    # Check nested steps raise an exception
    try:
        with Recorder("Destination", "TestStep") as recorder:
            with recorder.step("Step 1"):
                with recorder.step("Nested Step"):
                    pass  # Should not get here
        assert False  # Should not get here
    except Exception as e:
        assert str(e) == 'cannot open a step within a step'

    # Check that a Recorder without a step raises an error
    try:
        with Recorder("Destination", "NoStep"):
            pass  # No steps here
        assert False  # Should not get here
    except ValueError as ve:
        assert str(ve) == 'your hook must at least perform one step!'

if __name__ == '__main__':
    test_step()

