import inspect
import sys

if sys.version_info < (3, 0):
    def getargspec_permissive(func):
        if inspect.ismethod(func):
            func = func.im_func
        if not (hasattr(func, "func_code") and hasattr(func, "func_defaults")):
            raise TypeError('{!r} missing func_code or func_defaults'.format(func))

        args, varargs, varkw = inspect.getargs(func.func_code)
        return inspect.ArgSpec(args, varargs, varkw, func.func_defaults)

    getargspec = getargspec_permissive
else:
    getargspec = inspect.getfullargspec

# Test the implementation of getargspec_permissive
def test_getargspec_permissive():
    def test_func(a, b=2, *args, **kwargs):
        return a + b

    if sys.version_info < (3, 0):
        spec = getargspec_permissive(test_func)
        assert spec.args == ['a', 'b']
        assert spec.defaults == (2,)
        assert spec.varargs == 'args'
        assert spec.keywords is None
    else:
        full_spec = getargspec(test_func)
        assert full_spec.args == ['a', 'b']
        assert full_spec.varargs == 'args'
        assert full_spec.varkw == 'kwargs'
        assert full_spec.defaults == (2,)

if __name__ == '__main__':
    test_getargspec_permissive()

