class JobSet:
    def __init__(self, jobs):
        self._jobs = iter(jobs)
        self._active_jobs = 0
        self._on_deck = None  # Setting initial _on_deck to None
        self._load_job()  # This is where the initial job loading happens

    def _load_job(self):
        if self._active_jobs == 0:  # Only try to load if no active job
            try:
                next_job = next(self._jobs)
            except StopIteration:
                self._on_deck = None
            else:
                if not isinstance(next_job, Job):
                    next_job = DefaultJob(next_job)
                self._on_deck = next_job
                self._active_jobs += 1

    def get_job(self):
        if self._on_deck is not None:
            job = self._on_deck
            self._active_jobs -= 1  # Decrement active jobs when the job is retrieved
            self._load_job()
            return job
        else:
            raise IndexError("no jobs available")

    def is_done(self):
        return self._active_jobs == 0

def test__load_job():
    jobs = [DefaultJob(i) for i in range(2)]
    job_set = JobSet(jobs)

    assert job_set._on_deck.get_call() == 0, "Initially, the _on_deck should have the first job with call 0"

    job = job_set.get_job()  # Retrieve the first job; no need to call _load_job directly
    assert job.get_call() == 0, "The job retrieved should have call 0"
    assert job_set._active_jobs == 1, "The _active_jobs should be 1 after retrieving the first job"

    job = job_set.get_job()  # Retrieve the second job
    assert job.get_call() == 1, "The job retrieved should have call 1"
    assert job_set._active_jobs == 0, "The _active_jobs should be 0 after retrieving the last job"

    # Test initialization with a non-Job instance which should get converted to DefaultJob
    non_job_instance = "non-job"
    job_set_with_non_job = JobSet([non_job_instance])
    assert isinstance(job_set_with_non_job._on_deck, DefaultJob), "Non-Job should be converted to DefaultJob"
    assert job_set_with_non_job._on_deck.get_call() == "non-job", "The _on_deck should hold the converted non-Job instance"

if __name__=='__main__':
    test__load_job()

