        self._kernel_alive = True
        self._beating = False
        self.iopub_stream = None
        self.hb_stream = None
        self.application = MockApplication()

    def start_hb(self, callback):
        if not self._beating:
            self._kernel_alive = True

            def ping_or_dead():
                self.hb_stream.flush()
                if self._kernel_alive:
                    self._kernel_alive = False
                    self.hb_stream.send(b'ping')
                    self.hb_stream.flush()
                else:
                    try:
                        callback()
                    except:
                        pass
                    finally:
                        self.stop_hb()

            def beat_received(msg):
                self._kernel_alive = True

            self.hb_stream.on_recv(beat_received)
            loop = ioloop.IOLoop.current()
            self._hb_periodic_callback = ioloop.PeriodicCallback(ping_or_dead, 1000)
            loop.add_timeout(time.time() + 1, self._really_start_hb)
            self._beating = True

    def _really_start_hb(self):
        if self._beating and not self.hb_stream.closed():
            self._hb_periodic_callback.start()

    def stop_hb(self):
        if self._beating:
            self._hb_periodic_callback.stop()
            self._beating = False
            if not self.hb_stream.closed():
                self.hb_stream.on_recv(None)

