    channel = BlockingStdInSocketChannel()

    # Test case 1: Retrieve a message correctly
    test_message = "Test message 1"
    channel.call_handlers(test_message)
    assert channel.get_msg(block=False) == test_message, "Failed to get the correct message"

    # Test case 2: Raise Empty when no message and block is False
    try:
        channel.get_msg(block=False)
        assert False, "Empty exception not raised when no message is available and block is False"
    except Empty:
        assert True, "Empty exception expected when no message is available and block is False"

