import time
import threading
from io import BytesIO

class BandwidthLimitedStream(object):
    def __init__(self, fileobj, leaky_bucket, transfer_coordinator,
                 time_utils=None, bytes_threshold=256 * 1024):
        self._fileobj = fileobj
        self._leaky_bucket = leaky_bucket
        self._transfer_coordinator = transfer_coordinator
        self._bandwidth_limiting_enabled = True
        self._bytes_seen = 0
        self._bytes_threshold = bytes_threshold

    def enable_bandwidth_limiting(self):
        self._bandwidth_limiting_enabled = True

    def disable_bandwidth_limiting(self):
        self._bandwidth_limiting_enabled = False

    def read(self, amount):
        if not self._bandwidth_limiting_enabled:
            return self._fileobj.read(amount)

        self._bytes_seen += amount
        if self._bytes_seen < self._bytes_threshold:
            return self._fileobj.read(amount)

        self._leaky_bucket.consume(self._bytes_seen)
        self._bytes_seen = 0
        return self._fileobj.read(amount)

class LeakyBucket(object):
    def __init__(self, max_rate):
        self._max_rate = max_rate
        self._lock = threading.Lock()
        self._current_rate = 0
        self._last_consume_time = time.time()

    def consume(self, amount):
        with self._lock:
            current_time = time.time()
            time_passed = current_time - self._last_consume_time

            potential_bandwidth = self._current_rate - (self._max_rate * time_passed)
            available_bandwidth = min(self._max_rate, max(0, potential_bandwidth))

            if amount <= available_bandwidth:
                self._current_rate -= amount
            else:
                needed_time = (amount - available_bandwidth) / self._max_rate
                time.sleep(needed_time)
                self._current_rate = 0

            self._current_rate += amount
            self._last_consume_time = current_time

class TransferCoordinatorStub(object):
    exception = None

def test_read():
    file_content = b"Testing BandwidthLimitedStream" * 50
    fileobj = BytesIO(file_content)
    leaky_bucket = LeakyBucket(max_rate=1024)
    transfer_coordinator = TransferCoordinatorStub()
    bandwidth_limited_stream = BandwidthLimitedStream(fileobj, leaky_bucket, transfer_coordinator)

    expected_data = file_content[0:10240]

    assert bandwidth_limited_stream.read(10240) == expected_data
    assert bandwidth_limited_stream.read(0) == b''
    assert bandwidth_limited_stream.read(5) == file_content[10240:10245]

if __name__ == '__main__':
    test_read()

