import math

class BezierShape:
    @staticmethod
    def _cubic_bernstein_extrema(p0, p1, p2, p3):
        """Find extremas of a function of real domain defined by evaluating a cubic bernstein polynomial of given bernstein coefficients."""
        a = 3.*(p3-p0+3.*(p1-p2))
        b = 6.*(p0+p2-2.*p1)
        c = 3.*(p1-p0)

        if a == 0:
            if b == 0:
                return ()  # constant
            return (-c / b,)  # linear

        d = b*b - 4.*a*c
        if d < 0:
            return ()

        k = -2. * a
        if d == 0:
            return (b / k,)

        r = math.sqrt(d)
        return ((b + r) / k, (b - r) / k)

    @staticmethod
    def _cubic_bernstein(p0, p1, p2, p3, t):
        """Evaluate polynomial of given bernstein coefficients using de Casteljau's algorithm."""
        u = 1 - t
        return p0*(u**3) + 3*t*u*(p1*u + p2*t) + p3*(t**3)

def test__cubic_bernstein():
    assert BezierShape._cubic_bernstein(0, 1, 2, 3, 0) == 0
    assert BezierShape._cubic_bernstein(0, 1, 2, 3, 0.5) == 1.5
    assert BezierShape._cubic_bernstein(0, 1, 2, 3, 1) == 3

if __name__ == "__main__":
    test__cubic_bernstein()
    p0, p1, p2, p3 = 0, 1, 2, 3
    t = 0.5
    result = BezierShape._cubic_bernstein(p0, p1, p2, p3, t)
    print("Result:", result)

