TIMEZONE = pendulum.timezone('UTC')
utc = pendulum.timezone('UTC')


def is_localized(value):
    return value.utcoffset() is not None


def is_naive(value):
    return value.utcoffset() is None


def make_aware(value, timezone=None):
    if timezone is None:
        timezone = TIMEZONE

    if is_localized(value):
        raise ValueError(
            "make_aware expects a naive datetime, got %s" % value)
    if hasattr(value, 'fold'):
        value = value.replace(fold=1)
    if hasattr(timezone, 'localize'):
        return timezone.localize(value)
    elif hasattr(timezone, 'convert'):
        return timezone.convert(value)
    else:
        return value.replace(tzinfo=timezone)


def test_make_aware():
    naive_datetime = dt.datetime(2022, 1, 1, 0, 0, 0)
    timezone = pendulum.timezone('Europe/Paris')

    # Test that naive datetime is correctly made aware with default timezone
    assert make_aware(naive_datetime).tzinfo == TIMEZONE

    # Test that naive datetime is correctly made aware with specified timezone
    assert make_aware(naive_datetime, timezone).tzinfo == timezone

    # Test that the function raises a ValueError for already-aware datetime objects
    aware_datetime = make_aware(naive_datetime)
    try:
        make_aware(aware_datetime)
        assert False, "make_aware did not raise ValueError for aware datetime"
    except ValueError:
        pass  # This is expected


if __name__ == "__main__":
    test_make_aware()
    print("All tests passed.")

