class DatastoreHook:

    def __init__(self, api_version='v1'):
        self.connection = None
        self.api_version = api_version
        self.num_retries = 5

    def get_conn(self):
        # Use mock instead of real Google API client
        if not self.connection:
            self.connection = mock.Mock()
        return self.connection

    def rollback(self, transaction):
        conn = self.get_conn()
        return conn.projects().rollback(
            projectId="your_project_id", body={'transaction': transaction}
        ).execute(num_retries=self.num_retries)

def test_rollback():
    hook = DatastoreHook()

    # Using the actual hook instance to mock get_conn method
    with mock.patch.object(hook, 'get_conn') as mock_get_conn:
        mock_service = mock.Mock()
        mock_projects = mock.Mock()
        mock_rollback = mock.Mock()

        mock_get_conn.return_value = mock_service
        mock_service.projects.return_value = mock_projects
        mock_projects.rollback.return_value = mock_rollback
        mock_rollback.execute.return_value = 'rollback_response'

        transaction_id = "your_transaction_id"
        response = hook.rollback(transaction_id)

        mock_service.projects.assert_called_once()
        mock_projects.rollback.assert_called_once_with(
            projectId="your_project_id", body={'transaction': transaction_id}
        )
        assert response == 'rollback_response'
        mock_rollback.execute.assert_called_with(num_retries=5)

