import functools
from collections import OrderedDict, defaultdict

class CommandError(Exception):
    """Base error type for errors."""
    def __init__(self, msg, exit_status=1):
        super().__init__(msg)
        self.exit_status = exit_status

class Command:
    """Base class for commands."""
    _all_commands = OrderedDict()

    CommandDict = functools.partial(defaultdict, OrderedDict)
    _registered_commands = CommandDict()

    @classmethod
    def register(cls, CommandSubClass):
        """A class decorator for Command classes to register."""
        for name in [CommandSubClass.name()] + CommandSubClass.aliases():
            if name in cls._registered_commands[cls]:
                raise ValueError("Command already exists: " + name)
            cls._registered_commands[cls][name] = CommandSubClass
        return CommandSubClass

    @classmethod
    def name(cls):
        return cls.NAME if hasattr(cls, "NAME") else cls.__name__

    @classmethod
    def help(cls):
        return cls.HELP if hasattr(cls, "HELP") else None

    @classmethod
    def desc(cls):
        return cls.DESC if hasattr(cls, "DESC") else cls.help()

    @classmethod
    def aliases(cls):
        return cls.ALIASES if hasattr(cls, "ALIASES") else []

    @classmethod
    def loadCommandMap(cls, subparsers=None, instantiate=True, **cmd_kwargs):
        """Instantiate each registered command to a dict mapping name/alias to instance."""
        if not cls._registered_commands:
            raise ValueError("No commands have been registered with {}".format(cls))

        all = {}
        for Cmd in set(cls._registered_commands[cls].values()):
            cmd = Cmd(subparsers=subparsers, **cmd_kwargs) if instantiate else Cmd
            for name in [Cmd.name()] + Cmd.aliases():
                all[name] = cmd
        return all

# Implement mock test commands for testing.
class TestCommand(Command):
    NAME = "test"
    ALIASES = ["TEST", "testcmd"]

class NoAliasCommand(Command):
    NAME = "noalias"

def test_loadCommandMap():
    Command.register(TestCommand)
    Command.register(NoAliasCommand)

    command_map = Command.loadCommandMap(instantiate=False)

    # Test 1: Verify that a registered command is in the command map
    assert "test" in command_map
    # Test 2: Verify aliases of a registered command are in the command map
    assert "TEST" in command_map and command_map["TEST"] is command_map["test"]
    # Test 3: Verify a registered command with no aliases is in the command map
    assert "noalias" in command_map

    # Cleanup: Make sure to cleanup the registration for repeatable test runs
    Command._registered_commands[Command].clear()

if __name__ == '__main__':
