    # Test with a word starting with letter 'l'
    results = do_fuzzy("lilas")
    for letter in string.ascii_lowercase:
        if letter != 'l':
            # Should generate substitutions with every letter except 'l'
            assert (letter + 'ilas') in results
        # Should generate insertions with every letter
        assert (letter + 'lilas') in results
    # Test with empty string
