T = TypeVar("T")

class _EmptySequence:
    def __repr__(self):
        return "()"

    def __bool__(self):
        return False

    @property
    def is_empty(self) -> bool:
        return True

    @property
    def first(self) -> Optional[T]:
        return None

    @property
    def rest(self) -> '_EmptySequence':
        return self

    def cons(self, elem):
        return Cons(elem, self)

EMPTY = _EmptySequence()

class Cons:
    __slots__ = ("_first", "_rest")

    def __init__(self, first=None, seq: Optional[_EmptySequence] = None) -> None:
        self._first = first
        self._rest = seq or EMPTY

    @property
    def is_empty(self) -> bool:
        return False

    @property
    def first(self) -> Optional[T]:
        return self._first

    @property
    def rest(self) -> '_EmptySequence':
        return self._rest

    def cons(self, elem: T) -> '_EmptySequence':
        return Cons(elem, self)

class _Sequence:
    def __init__(self, s: Iterator, first: T) -> None:
        self.x = s
        self.prev = None
        self._first = first
        self._rest: Optional[_EmptySequence] = None

    @property
    def is_empty(self) -> bool:
        return False

    @property
    def first(self) -> Optional[T]:
        return self._first

    @property
    def rest(self) -> '_EmptySequence':
        if self._rest:
            return self._rest
        try:
            n = next(self.x)
            self._rest = _Sequence(self.x, n)
        except StopIteration:
            self._rest = EMPTY
        return self._rest

    def cons(self, elem):
        return Cons(elem, self)

def sequence(s: Iterable[T]) -> _EmptySequence:
    try:
        i = iter(s)
        return _Sequence(i, next(i))
    except StopIteration:
        return EMPTY

