                <TTL>3600</TTL>
                <ResourceRecords>
                    <ResourceRecord>
                        <Value>192.168.1.1</Value>
                    </ResourceRecord>
                </ResourceRecords>
            </ResourceRecordSet>
        </ResourceRecordSets>
    </Response>"""

    e_root = etree.fromstring(xml_data)
    connection = None
    zone_id = "ABC123"

    rrsets = list_resource_record_sets_by_zone_id_parser(e_root, connection, zone_id)

    rrset = None
    for r in rrsets:
        rrset = r

    assert rrset is not None
    assert rrset.kwargs.get('name') == 'example.com.'
    assert rrset.kwargs.get('records') == ['192.168.1.1']

if __name__ == '__main__':
    test_parse_rrset()

