def get_all_slots(cls):
    slots_iterator = (getattr(c, '__slots__', ()) for c in cls.__mro__)
    slots_converted = ((slots,) if isinstance(slots, str) else slots
                                for slots in slots_iterator)
    all_slots = set()
    all_slots.update(*slots_converted)
    return all_slots

class MetaSlotMachine(type):
    def __init__(cls, name, bases, dictionary):
        super(MetaSlotMachine, cls).__init__(name, bases, dictionary)
        cls.__all_slots__ = get_all_slots(cls)


class HasSlots(object, metaclass=MetaSlotMachine):
    __slots__ = ('__weakref__',)

    def __getstate__(self):
        if hasattr(self, '__dict__'):
            statedict = self.__dict__.copy()
        else:
            statedict = {}
        for slot in self.__all_slots__:
            try:
                value = getattr(self, slot)
                statedict[slot] = value
            except AttributeError:
                pass
        statedict.pop('__dict__', None)
        statedict.pop('__weakref__', None)
        return statedict

    def __setstate__(self, state):
        for key in state:
            setattr(self, key, state[key])

    def __dir__(self):
        result = set()
        result.update(dir(self.__class__), self.__all_slots__)
        if hasattr(self, '__dict__'):
            result.update(self.__dict__.keys())
        return list(result)

def test_get_all_slots():
    # Test case 1: A class with no parent classes (other than `object` with slots defined)
    class NoParentSlots(HasSlots):
        __slots__ = ("x",)

    # Test case 2: A class with one parent class that has slots defined
    class SingleParentSlots(NoParentSlots):
        __slots__ = ("y",)

    # Test case 3: A class with multiple parent classes in its hierarchy, each defining their own slots
    class MultipleParentSlots(SingleParentSlots):
        __slots__ = ("z",)

    assert get_all_slots(NoParentSlots) == {'x', '__weakref__'}, "Test case 1 failed"
    assert get_all_slots(SingleParentSlots) == {'x', 'y', '__weakref__'}, "Test case 2 failed"
    assert get_all_slots(MultipleParentSlots) == {'x', 'y', 'z', '__weakref__'}, "Test case 3 failed"

if __name__ == '__main__':
    test_get_all_slots()

