import re

OPERATORS = {'=', '!=', '<', '<=', '>=', '>'}

def escape_filter(value):
    """Strips any brackets () from filter."""
    if isinstance(value, int) or value.lower() == 'null':
        return value
    return re.sub('[()]+', '', value)

class Q(object):
    @classmethod
    def from_dict(cls, d):
        if not d:
            raise ValueError('Empty dictionary!')
        items = list(d.items())
        key, value = items.pop(0)
        q = cls(key, '=', value)
        for key, value in items:
            q = q & cls(key, '=', value)
        return q

    def __init__(self, name, op, value):
        self.name = name
        if op not in OPERATORS:
            raise ValueError('Invalid operator {}'.format(op))
        self.op = op
        self.value = escape_filter(value)       
        self.preceeding = None
        self.is_or = False

    def _set_preceeding(self, preceeding):
        self.preceeding = preceeding

    @property
    def as_filters(self):
        if self.preceeding is not None:
            filters = self.preceeding.as_filters
        else:
            filters = []

        filter_str = f'{self.name} {self.op} {self.value}'
        filters.append(filter_str if not self.is_or else f'OR {filter_str}')

        return filters

    def __or__(self, other_q):
        other_q._set_preceeding(self)
        other_q.is_or = True
        return other_q

    def __and__(self, other_q):
        other_q._set_preceeding(self)
        return other_q

def test_from_dict():
    q1 = Q.from_dict({'name': 'foo'})
    assert q1.as_filters == ['name = foo'], "Test with single condition failed."

    q2 = Q.from_dict({'age': 42, 'name': 'bar'})
    expected_filters = ['age = 42', 'name = bar']
    assert q2.as_filters == expected_filters, "Test with two conditions failed."

    try:
        Q.from_dict({})
    except ValueError as e:
        assert str(e) == 'Empty dictionary!', "Test with empty dictionary did not raise ValueError."

if __name__ == '__main__':
    test_from_dict()

