    unit1._serializeDecision = custom_serialize_decision
    ent1 = Entity("ent1", unit1)
    assert GenericSerializer.serializationDecision(ent1, serialized_classes, serialized_configured_units) is True

    # Unit without custom serialize decision
    unit2 = Unit("unit2")
    ent2 = Entity("ent2", unit2)
