        self.log = []
        self._stream = sys.stdout if stream else None
        self._env = env
        self._cwd = cwd
        self._shell = force_shell

    @property
    def last_returncode(self):
        try:
            return self.log[-1][1]
        except IndexError:
            raise RuntimeError('Nothing executed')

    @property
    def last_command(self):
        if not len(self.log):
            raise RuntimeError('Nothing executed')

        return self.log[-1][0]

    @property
    def last_output(self):
        if not len(self.log):
            raise RuntimeError('Nothing executed')

        return self.log[-1][2]

