        MockBackend.only_simulators = [
            MockBackend("backend1", False),
            MockBackend("backend1", False),
            MockBackend("backend2", True),
            MockBackend("backend3", False),
        ]
    unique_hardware_backends = []
    unique_names = []
    for back in MockBackend.only_simulators:
        # Only consider backend unique if it's not a simulator and name wasn't added before.
        if back.name() not in unique_names and not back.simulator():
            unique_hardware_backends.append(back)
            unique_names.append(back.name())
    if not unique_hardware_backends:
        raise ValueError("No backends available.")
    return unique_hardware_backends


