    # Test to ensure that duplicate backends are filtered out
    backends_list = get_unique_backends()
    backend_names = [backend.name() for backend in backends_list]
    assert len(backend_names) == len(set(backend_names)), "Duplicates were not filtered out."

    # Test to ensure that simulator backends are excluded
