def convert_video(in_file, out_file, print_cmd=False, pre_options='', **kwargs):
    options = []
    for k, v in kwargs.items():
        if isinstance(v, bool):
            if v:
                options.append('-{}'.format(k))
        elif k == 'log_level':
            assert v in [
                'quiet', 'panic', 'fatal', 'error', 'warning', 'info',
                'verbose', 'debug', 'trace'
            ]
            options.append('-loglevel {}'.format(v))
        else:
            options.append('-{} {}'.format(k, v))
    cmd = 'ffmpeg -y {} -i {} {} {}'.format(pre_options, in_file,
                                            ' '.join(options), out_file)
    if print_cmd:
        print(cmd)
    # Here, instead of calling subprocess.call, the function now returns the cmd
    # since we are using a mock in test_cut_video to not actually run the command.
    return cmd  # subprocess.call(cmd, shell=True) is replaced with this

def cut_video(in_file, out_file, start=None, end=None, vcodec=None, acodec=None, log_level='info', print_cmd=False, **kwargs):
    options = {'log_level': log_level}
    if vcodec is None:
        options['vcodec'] = 'copy'
    if acodec is None:
        options['acodec'] = 'copy'
    if start:
        options['ss'] = start
    else:
        start = 0
    if end:
        options['t'] = end - start
    # The return statement is added here to return the output of convert_video
    return convert_video(in_file, out_file, print_cmd, **options)

def mock_subprocess_call(cmd, shell):
    return cmd  # Pretend we run the command and just return it

def test_cut_video():
    original_call = subprocess.call
    try:
        subprocess.call = mock_subprocess_call  # Replace the actual call with our mock
        command = cut_video("input.mp4", "output.mp4", start=10, end=20)

        # Test if the ffmpeg command starts correctly
        assert command.startswith("ffmpeg -y")

        # Test if the input file is specified correctly
        assert "-i input.mp4" in command

        # Test if the options 'ss' (start) and 't' (duration) are correctly set
        assert "-ss 10" in command
        assert "-t 10" in command  # 20 - 10 = 10 seconds duration
    finally:
        subprocess.call = original_call  # Restore the original subprocess.call

if __name__ == '__main__':
    check_executable('ffmpeg')
    test_cut_video()  # Run the tests

