    def __init__(self, ready_status, wall_time_seconds):
        self._ready = ready_status
        self.wall_time = wall_time_seconds
        self._submission_time = datetime.now() - timedelta(seconds=5)

    def ready(self):
        return self._ready

    def elapsed(self):
        if self.ready():
            return int(round(self.wall_time))  # Make sure to return an integer

        now = datetime.now()
        elapsed_time = _total_seconds(now - self._submission_time)
        return int(round(elapsed_time))  # Ensure an integer is returned for consistency

