def test_release():
    sem = TaskSemaphore(1)
    tag = "test_tag"

    # Acquire the semaphore, which should work because it's initially available
    sem.acquire(tag)

    # Release the semaphore, this should not raise an error
    sem.release(tag)

    # Acquire the semaphore again, this should work because it was released
    sem.acquire(tag)

    # Use a separate thread to test that the semaphore is actually blocking
    result = {}

    def try_acquire(result, idx):
        try:
            sem.acquire(tag, False)
            result[idx] = True
        except NoResourcesAvailable:
            result[idx] = False

    # Start a thread that will attempt to acquire the semaphore and assert it fails
    acquire_thread = threading.Thread(target=try_acquire, args=(result, 1))
    acquire_thread.start()
    acquire_thread.join()

    # As the semaphore is acquired in the main thread, the thread should return False
    assert result[1] == False, "Should not be able to acquire an already-acquired semaphore"

    # Release the semaphore to allow the thread to acquire it
    sem.release(tag)

    # The thread should now be able to acquire the semaphore
    acquire_thread = threading.Thread(target=try_acquire, args=(result, 2))
    acquire_thread.start()
    acquire_thread.join()
    assert result[2] == True, "Should be able to acquire semaphore after release"


def main():
    test_release()


