class NodeException(Exception):
    """Node exception (used by all nodes except Program)."""
    pass

class Node:
    """Base class for AST nodes.

    This is a virtual class and should not be instantiated.
    """

    def __init__(self, type, children, value):
        """Create a node."""
        self.type = type
        self.children = children
        self.value = value

    def to_string(self, _=None):
        """Print the node."""
        print("Node: ", self.type)

class Id(Node):
    """Node for an id."""

    def __init__(self, id, line, file):
        super().__init__("id", None, None)
        self.name = id
        self.line = line
        self.file = file
        self.is_bit = False

    def to_string(self, indent):
        ind = indent * ' '
        print(ind, 'id', self.name)

    def qasm(self, prec=15):
        return self.name

    def latex(self, prec=15, nested_scope=None):
        # The string should start with a double backslash to escape the LaTeX command properly
        if not nested_scope:
            return "\\textrm{" + self.name + "}"
        else:
            if self.name not in nested_scope[-1]:
                raise NodeException("Expected local parameter name: ",
                                    "name=%s, " % self.name,
                                    "line=%s, " % self.line,
                                    "file=%s" % self.file)
            else:
                return nested_scope[-1][self.name].latex(prec,
                                                         nested_scope[0:-1])

