    # Test case 1: No nested scope
    id_node = Id("test_id", 1, "test_file")
    assert id_node.latex() == "\\textrm{test_id}"

    # Test case 2: A NodeException should be raised when the name is not in the nested scope
    nested_scope = [{'other_id': id_node}, {'test_id': id_node}]
    try:
        id_node.latex(nested_scope=nested_scope)
        raise AssertionError("NodeException was not raised when it should have been")
    except NodeException:
        pass  # This is expected

    # Test case 3: The function should correctly use the nested scope to format
    nested_scope = [{'test_id': id_node}]
    assert id_node.latex(nested_scope=nested_scope) == "\\textrm{test_id}"

if __name__ == '__main__':
    test_latex()

