class Invoice:

    def __init__(self, user, is_paid):
        self.user = user
        self.is_paid = is_paid

    @property
    def allowed_to_pay(self):
        return not self.is_paid


class CreditNoteController:

    def __init__(self, credit_note):
        self.credit_note = credit_note

    @classmethod
    def generate_from_invoice(cls, invoice, value):
        credit_note = CreditNote.create(invoice, value, "ONE MOMENT")
        credit_note.reference = "Generated credit note %d" % credit_note.id
        return cls(credit_note)

    def apply_to_invoice(self, invoice):
        if not invoice.allowed_to_pay:
            raise ValueError("The given invoice is not allowed to be paid.")

        CreditNoteApplication.create(self.credit_note, invoice, self.credit_note.value,
                                     "Applied credit note #%d" % self.credit_note.id)
        invoice.is_paid = True


def test_apply_to_invoice():
    # Test case 1: Invoice should be marked as paid after applying the credit note
    invoice = Invoice(user="test_user", is_paid=False)
    credit_note_value = 100
    credit_note_controller = CreditNoteController.generate_from_invoice(invoice, credit_note_value)
    credit_note_controller.apply_to_invoice(invoice)
    assert invoice.is_paid, "Invoice should be marked as paid after applying the credit note"

    # Test case 2: Applying a credit note to an already paid invoice should raise an error
    invoice_already_paid = Invoice(user="test_user", is_paid=True)
    try:
        credit_note_value = 50
        credit_note_controller = CreditNoteController.generate_from_invoice(invoice_already_paid, credit_note_value)
        credit_note_controller.apply_to_invoice(invoice_already_paid)
        assert False, "ValueError should have been raised"
    except ValueError:
        assert True, "ValueError was correctly raised"

    # Test case 3: Create and apply a credit note with a positive value
    invoice_positive_payment = Invoice(user="test_user_positive", is_paid=False)
    credit_note_controller = CreditNoteController.generate_from_invoice(invoice_positive_payment, 50)
    assert credit_note_controller.credit_note.value <= 0, "Credit note value should be negative"
    credit_note_controller.apply_to_invoice(invoice_positive_payment)
    assert invoice_positive_payment.is_paid, "Invoice should be marked as paid after applying the credit note"

if __name__ == '__main__':
