    assert queue.put(3) == True  # Should allow third item
    assert queue.put(4) == False # Should not allow fourth item, queue is full
    assert queue.full()          # The queue should now be full
    # Empty one slot
    queue.get()                  
    assert queue.put(5) == True  # Now should allow another item, as one slot is free

if __name__=='__main__':
    test_put()

