import logging
from functools import wraps
from unittest.mock import Mock

_logger = logging.getLogger(__name__)

def catch(logger):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception:
                logger.warning(f"Exception raised in decorator: {func.__name__}")

        return wrapper
    return decorator

@catch(_logger)
def _log_message(logger, func_name, message):
    logger.info(f"{func_name} - {message}")

def log_message(logger, message=""):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            _log_message(logger, func.__name__, message)
            result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

# Test code for the log_message function
def test_log_message():
    mock_logger = Mock()
    test_message = "Testing log_message"

    @log_message(mock_logger, test_message)
    def test_function():
        return "Function executed"

    assert test_function() == 'Function executed'
    mock_logger.info.assert_called_once_with(f"test_function - {test_message}")

    mock_logger.reset_mock()
    test_message = ""

    @log_message(mock_logger, test_message)
    def another_function():
        return "Another function executed"

