from io import StringIO

class Layout:
    def __init__(self, *children):
        self.children = children

    def accept(self, writer):
        writer.format_children(self)

class Text:
    def __init__(self, text=''):
        self.text = text

    def accept(self, writer):
        writer.write(self.text)

class Table:
    def __init__(self, cols, *children):
        self.cols = cols
        self.children = children

    def accept(self, writer):
        writer.format_children(self)

class BaseWriter:
    """base class for ureport writers"""

    def begin_format(self):
        """begin to format a layout"""
        pass

    def end_format(self):
        """finished to format a layout"""
        pass

    def format_children(self, layout):
        """recurse on the layout children and call their accept method
        (see the Visitor pattern)
        """
        for child in getattr(layout, "children", ()):
            child.accept(self)

    def write(self, string):
        """write a string in the output buffer"""
        self.out.write(string)

    def get_table_content(self, table):
        """trick to get table content without actually writing it
        return an aligned list of lists containing table cells values as string
        """
        result = [[]]
        cols = table.cols
        for cell in self.compute_content(table):
            if cols == 0:
                result.append([])
                cols = table.cols
            cols -= 1
            result[-1].append(cell)
        # fill missing cells
        while len(result[-1]) < table.cols:
            result[-1].append("")
        return result

    def compute_content(self, layout):
        """trick to compute the formatting of children layout before actually
        writing it
        return an iterator on strings (one for each child element)
        """
        out = self.out
        try:
            for child in layout.children:
                stream = StringIO()
                self.out = stream
                child.accept(self)
                yield stream.getvalue()
        finally:
            self.out = out

# Test code for the `get_table_content` function
def test_get_table_content():
    writer = BaseWriter()
    writer.out = StringIO()

    table = Table(2, Text("cell1"), Text("cell2"), Text("cell3"), Text("cell4"), Text("cell5"))
    result = writer.get_table_content(table)
    # Test that the resulting table content is correct
    assert result == [["cell1", "cell2"], ["cell3", "cell4"], ["cell5", ""]], "Test with an odd number of cells failed."

    # Test with an even number of cells (2 rows, 2 columns)
    table = Table(2, Text("cellA"), Text("cellB"), Text("cellC"), Text("cellD"))
    result = writer.get_table_content(table)
    assert result == [["cellA", "cellB"], ["cellC", "cellD"]], "Test with an even number of cells failed."

    # Test with more cells than columns defines
    table = Table(3, Text("cell1"), Text("cell2"), Text("cell3"), Text("cell4"))
    result = writer.get_table_content(table)
    assert result == [["cell1", "cell2", "cell3"], ["cell4", "", ""]], "Test with incomplete row failed."

# Execute test code when run as a script
if __name__ == "__main__":
    test_get_table_content()

