class MessageDefinitionsStore:
    def get_message_definitions(self, msgid):
        # For test purposes, we'll use a predefined dictionary
        message_definitions = {
            'known_msgid': [MessageDefinition('KNOWN_SYMBOL')],
            'multiple_symbols_msgid': [MessageDefinition('SYMBOL1'), MessageDefinition('SYMBOL2')],
        }
        if msgid in message_definitions:
            return message_definitions[msgid]
        else:
            raise UnknownMessageError()

