    # Test with valid input
    assert cls_from_str("builtins:int") == int, "Error: cls_from_str did not correctly identify 'builtins:int'"
    assert cls_from_str(__name__ + ":Example") == Example, "Error: cls_from_str did not correctly identify '__main__:Example'"

    # Test with a non-existing class
    try:
        cls_from_str("builtins:NonExistentClass")
        assert False, "Error: cls_from_str should have raised an AttributeError for a non-existing class"
    except AttributeError:
        pass  # Expected exception

    # Test with improperly formatted class description
    try:
        cls_from_str("this is not properly formatted")
        assert False, "Error: cls_from_str should have raised a ValueError for an improperly formatted class description"
    except ValueError:
        pass  # Expected exception

