import json
from requests.models import Response


class BackendException(Exception):
    """
    Specific backend exception class.
    """
    def __init__(self, code, message, response=None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.response = response

    def __str__(self):
        response_content = self.response.content if self.response else None
        if self.response and isinstance(response_content, bytes):
            response_content = response_content.decode('utf-8')
        return f"BackendException raised with code {self.code} and message: {self.message} - {response_content}"


class Backend:
    """
    Backend client class with only the decode function for testing purposes.
    """
    @staticmethod
    def decode(response):
        """
        Decodes and returns the response as JSON (dict) or raise BackendException
        """
        try:
            response.raise_for_status()
        except Exception as e:  # Simulate requests.HTTPError
            raise BackendException(code=response.status_code, message=str(e), response=response)
        else:
            resp_json = response.json()
            error = resp_json.get('_error', None)
            if error:
                raise BackendException(code=error['code'], message=error['message'], response=response)
            return resp_json


def test_decode():
    successful_response = Response()
    successful_response.status_code = 200
    successful_response._content = json.dumps({'key': 'value'}).encode('utf-8')

    error_response = Response()
    error_response.status_code = 200
    error_response._content = json.dumps({
        '_error': {
            'code': 400,
            'message': 'Error message'
        }
    }).encode('utf-8')

    failed_status_response = Response()
    failed_status_response.status_code = 404
    failed_status_response._content = b'Not Found'

    # Test 1: Successful Response
    try:
        result = Backend.decode(successful_response)
        assert result == {'key': 'value'}, "Test 1: Failed to decode successful response."
    except BackendException:
        assert False, "Test 1: Unexpected BackendException raised for successful response."

    # Test 2: Error Response
    try:
        Backend.decode(error_response)
        assert False, "Test 2: BackendException was expected but not raised."
    except BackendException as e:
        assert e.code == 400 and e.message == 'Error message', "Test 2: Incorrect BackendException details."

    # Test 3: Failed Status Response
    try:
        Backend.decode(failed_status_response)
        assert False, "Test 3: BackendException was expected but not raised."
    except BackendException as e:
        assert e.code == 404 and e.message == '404 Client Error: None for url: None', "Test 3: Incorrect BackendException details."


if __name__ == '__main__':
    test_decode()

