class Lookup:
    @classmethod
    def whois(cls, whois_server, domain=None, timeout=None):
        # Using a default value for domain and timeout since
        # they are no longer coming from the PyFunceble configuration
        if domain is None:
            domain = "your_default_domain"
        if timeout is None:
            timeout = 10  # Default timeout value, you may adjust as needed.

        if whois_server:
            req = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

            if timeout % 3 == 0:
                req.settimeout(timeout)
            else:
                req.settimeout(3)

            try:
                req.connect((whois_server, 43))
            except socket.error:
                return None

            req.send((domain + "\r\n").encode())

            response = b""

            while True:
                try:
                    data = req.recv(4096)
                except (socket.timeout, ConnectionResetError):
                    req.close()
                    return None

                response += data

                if not data:
                    break

            req.close()

            try:
                return response.decode()

            except UnicodeDecodeError:
                return response.decode("utf-8", "replace")

        return None

