def is_url(url):
    if '://' not in url:
        return False
    proto, addr = url.split('://', 1)
    if proto.lower() not in ['tcp','pgm','epgm','ipc','inproc']:
        return False
    return True

def disambiguate_ip_address(ip, location=None):
    if ip in ('0.0.0.0', '*'):
        try:
            external_ips = socket.gethostbyname_ex(socket.gethostname())[2]
        except (socket.gaierror, IndexError):
            external_ips = []
        if location is None or location in external_ips or not external_ips:
            ip='127.0.0.1'
        elif location:
            return location
    return ip

def disambiguate_url(url, location=None):
    if not is_url(url):
        return url
    proto_addr = url.split('://')
    proto, addr = proto_addr
    lis = addr.split(':')
    addr, s_port = lis
    ip = disambiguate_ip_address(addr, location)
    return "%s://%s:%s" % (proto, ip, s_port)

def test_disambiguate_url():
    # Test case 1: Check if '*' in URL is converted to '127.0.0.1'
    assert disambiguate_url('tcp://*:1234') == 'tcp://127.0.0.1:1234'

    # Test case 2: Check if '0.0.0.0' in URL is also converted to '127.0.0.1'
    assert disambiguate_url('tcp://0.0.0.0:1234') == 'tcp://127.0.0.1:1234'

    # Test case 3: Check if a non-wildcard IP is left unchanged
    assert disambiguate_url('tcp://192.168.1.10:4321') == 'tcp://192.168.1.10:4321'

    # Additional test cases can be added if needed

if __name__ == '__main__':
    test_disambiguate_url()

