        pass

    @abstractmethod
    def __len__(self):
        pass

    @abstractmethod
    def raw_bytes(self):
        pass

    @abstractmethod
    def write_to(self, out):
        pass

    @classmethod
    @abstractmethod
    def from_stream(cls, stream, point_format_id, count):
        pass

    @classmethod
    @abstractmethod
    def from_compressed_buffer(
            cls, compressed_buffer, point_format_id, count, laszip_vlr
    ):
        pass

    @classmethod
    @abstractmethod
    def empty(cls, point_format_id):
        pass


class PackedPointRecord(IPointRecord):
    def __init__(self, data, point_format=None):
        self.array = data
        if point_format is None:
            point_format = point_format_id
        self.point_format = point_format

    @property
    def point_size(self):
        return self.array.dtype.itemsize

    @property
    def actual_point_size(self):
        return self.array.dtype.itemsize

    @classmethod
    def from_stream(cls, stream, point_format, count):
        point_data_buffer = bytearray(stream.read(count * point_format.itemsize))
        data = np.frombuffer(point_data_buffer, dtype=point_format)

        if len(point_data_buffer) < count * point_format.itemsize:
            raise ValueError("The byte stream does not contain enough bytes.")

        return cls(data, point_format)

    def __getitem__(self, item):
        return self.array[item]

    def __setitem__(self, key, value):
        self.array[key] = value

    def __len__(self):
        return self.array.shape[0]

    def raw_bytes(self):
        return self.array.tobytes()

    def write_to(self, out):
        out.write(self.raw_bytes())

    @classmethod
    def from_compressed_buffer(cls, compressed_buffer, point_format_id, count, laszip_vlr):
        raise NotImplementedError("This method is not implemented for PackedPointRecord")

    @classmethod
    def empty(cls, point_format):
        data = np.zeros(0, dtype=point_format)
        return cls(data, point_format)

