    try:
        packed_point_record_partial = PackedPointRecord.from_stream(stream_partial, point_format, 2)
    except ValueError as e:
        assert str(e) == "The byte stream does not contain enough bytes.", "from_stream should raise a ValueError for a partially filled buffer."

