class Striplog(object):
    """
    A Striplog is a sequence of intervals.
    """
    def __init__(self, list_of_Intervals, source=None, order='auto'):
        self.source = source
        self.__list = list_of_Intervals
        self.order = order

    def __repr__(self):
        length = len(self.__list)
        details = f"start={self.start.z}, stop={self.stop.z}"
        return f"Striplog({length} Intervals, {details})"

    def __getitem__(self, key):
        result = self.__list[key]
        return Striplog(result) if isinstance(result, list) else result

    def __len__(self):
        return len(self.__list)

    def __iter__(self):
        return iter(self.__list)

    def copy(self):
        """Returns a shallow copy."""
        return Striplog([i.copy() for i in self],
                        order=self.order,
                        source=self.source)

