import os
import re
import sys
import keyword
import builtins

class AliasError(Exception):
    pass

class InvalidAliasError(AliasError):
    pass

class AliasManager:
    def __init__(self):
        self.alias_table = {}
        self.default_aliases = self.get_default_aliases()
        self.exclude_aliases()
        self.init_aliases()

    def exclude_aliases(self):
        no_alias = set(['cd','popd','pushd','dhist','alias','unalias'])
        no_alias.update(set(keyword.kwlist))
        no_alias.update(set(builtins.__dict__.keys()))
        self.no_alias = no_alias

    def init_aliases(self):
        for name, cmd in self.default_aliases:
            self.soft_define_alias(name, cmd)

    def soft_define_alias(self, name, cmd):
        try:
            self.define_alias(name, cmd)
        except AliasError as e:
            print("Invalid alias: %s" % e)

    def define_alias(self, name, cmd):
        nargs = self.validate_alias(name, cmd)
        self.alias_table[name] = (nargs, cmd)

    def validate_alias(self, name, cmd):
        if name in self.no_alias:
            raise InvalidAliasError("The name %s can't be aliased "
                                    "because it is a keyword or builtin." % name)
        if not isinstance(cmd, str):  # Changed from basestring to str for Python 3 compatibility
            raise InvalidAliasError("An alias command must be a string, "
                                    "got: %r" % cmd)
        nargs = cmd.count('%s')
        if nargs>0 and cmd.find('%l')>=0:
            raise InvalidAliasError('The %s and %l specifiers are mutually '
                                    'exclusive in alias definitions.')
        return nargs

    def get_default_aliases(self):
        if os.name == 'posix':
            default_aliases = [('mkdir', 'mkdir'), ('rmdir', 'rmdir'),
                               ('mv', 'mv -i'), ('rm', 'rm -i'), ('cp', 'cp -i'),
                               ('cat', 'cat'),
                               ]
        elif os.name in ['nt', 'dos']:
            default_aliases = [('ls', 'dir /on'),
                               ('ddir', 'dir /ad /on'), ('ldir', 'dir /ad /on'),
                               ('mkdir', 'mkdir'), ('rmdir', 'rmdir'),
                               ('echo', 'echo'), ('ren', 'ren'), ('copy', 'copy'),
                               ]
        else:
            default_aliases = []

        return default_aliases


def test_validate_alias():
    alias_manager = AliasManager()

    assert alias_manager.validate_alias('test_alias', 'echo test') == 0
    assert alias_manager.validate_alias('test_alias_with_args', 'echo %s %s') == 2

    try:
        alias_manager.validate_alias('cd', 'echo cd')
    except InvalidAliasError as e:
        assert str(e) == "The name cd can't be aliased because it is a keyword or builtin."


if __name__ == '__main__':
    test_validate_alias()

