import os
from datetime import datetime

# Base class Item
class Item(object):
    def __init__(self, path):
        self.path = path
        self.children = []
        self.parent = None
        self._fetched = False

    def __repr__(self):
        return '<{0} {1}>'.format(self.__class__.__name__, self.path)

    def fetchChildren(self):
        if not self.canFetchMore():
            return []
        children = self._fetchChildren()
        self._fetched = True
        return children

    def _fetchChildren(self):
        return []

    def canFetchMore(self):
        return not self._fetched

    def refetch(self):
        for child in self.children[:]:
            self.removeChild(child)
        self._fetched = False

# Item-derived classes
class File(Item):
    def __init__(self, path):
        super(File, self).__init__(path)

class Computer(Item):
    def __init__(self, path='/'):
        super(Computer, self).__init__(path)

class Mount(Item):
    def __init__(self, path):
        super(Mount, self).__init__(path)

class Directory(Item):
    def __init__(self, path):
        super(Directory, self).__init__(path)

    def _fetchChildren(self):
        children = []
        paths = []
        for name in os.listdir(self.path):
            paths.append(os.path.normpath(os.path.join(self.path, name)))

        for path in paths:
            try:
                child = ItemFactory(path)
            except ValueError:
                pass
            else:
                children.append(child)
        return children

# Factory function to create the appropriate Item subclass
def ItemFactory(path):
    if not path:
        return Computer()
    elif os.path.isfile(path):
        return File(path)
    elif os.path.ismount(path):
        return Mount(path)
    elif os.path.isdir(path):
        return Directory(path)
    else:
        raise ValueError('Could not determine correct type for path: {0}'.format(path))

# Test function
def test_fetchChildren():
    test_dir = Directory('.')
    children = test_dir.fetchChildren()
    assert len(children) > 0, "fetchChildren returns no items in a non-empty directory"

    test_dir = Directory('/')
    children = test_dir.fetchChildren()
    assert children, "fetchChildren returns no items in the root directory"

    # Assuming '/dev/null' is an existing file on the system.
    try:
        test_dir = Directory('/dev/null')
    except ValueError:
        pass
    except Exception:
        assert False, "Directory constructor did not raise a ValueError for a non-directory path"

if __name__=='__main__':
    test_fetchChildren()

