import pandas as pd

ACTIVITY_COLUMN_ORDER = ['seconds', 'altitude', 'cadence', 'distance', 'heartrate', 'power', 'speed', 'temperature']
# Added 'alt' mapping to 'altitude' in the ACTIVITY_COLUMN_TRANSLATION dictionary.
ACTIVITY_COLUMN_TRANSLATION = {
    'km': 'distance',
    'kph': 'speed',
    'watts': 'power',
    'alt': 'altitude',  # Corrected here
    'hr': 'heartrate'   # Assuming 'hr' should be translated to 'heartrate'
}

DEFAULT_HOST = "http://localhost:12021/"
SAMPLE_ACTIVITY_LIST_DATA = "date,time,duration,average_speed,average_power,average_heart_rate,TSS\n\
2021-07-27,08:30:00,2:30:00,20,150,80,80\n\
2021-07-28,08:15:00,1:45:00,15,120,70,50\n\
"
SAMPLE_ACTIVITY_DATA = '{"RIDE": {"SAMPLES": [{"secs": 0, "km": 0, "kph": 20, "watts": 200, "hr": 70, "alt": 800}]}}'

class GoldenCheetahClient:
    def __init__(self, athlete=None, host=DEFAULT_HOST):
        if athlete is not None:
            self.athlete = athlete
        self.host = host

    def get_activities(self, filenames):
        return [self.get_activity(f) for f in filenames]

    def get_activity(self, filename):
        return self._request_activity_data(self.athlete, filename)

    def _request_activity_data(self, athlete, filename):
        response = self._get_request(self._activity_endpoint(athlete, filename))
        activity = pd.DataFrame(response['RIDE']['SAMPLES'])
        activity = activity.rename(columns=ACTIVITY_COLUMN_TRANSLATION)

        activity.index = pd.to_timedelta(activity.secs, unit='s')
        activity.drop('secs', axis=1, inplace=True)

        return activity[[i for i in ACTIVITY_COLUMN_ORDER if i in activity.columns]]

    def _activity_endpoint(self, athlete, filename):
        return '{host}{athlete}/activity/{filename}'.format(
            host=self.host,
            athlete=quote_plus(athlete),
            filename=filename
        )

    @lru_cache(maxsize=256)
    def _get_request(self, endpoint):
        if "/activity/" in endpoint:
            return pd.read_json(StringIO(SAMPLE_ACTIVITY_DATA))
        else:
            return pd.read_csv(StringIO(SAMPLE_ACTIVITY_LIST_DATA))

def test__request_activity_data():
    athlete = "John Doe"
    client = GoldenCheetahClient(athlete=athlete)
    filenames = ["2021_07_27_08_30_00.json", "2021_07_28_08_15_00.json"]

    activity1 = client._request_activity_data(athlete, filenames[0])
    activity2 = client._request_activity_data(athlete, filenames[1])

    assert activity1.iloc[0]["altitude"] == 800
    assert activity2.index[-1].seconds == 0
    assert activity2["speed"][0] == 20

if __name__ == "__main__":
    test__request_activity_data()

