from collections import namedtuple

class FoldedCaseKeyedDict(dict):
    def __setitem__(self, key, value):
        super().__setitem__(key.lower(), value)

    def __getitem__(self, key):
        return super().__getitem__(key.lower())

    def get(self, key, default=None):
        return super().get(key.lower(), default)

class ContentType:
    """A simplified ContentType class."""

    def __init__(self, name, key):
        self.name = name
        self.key = key


class ContentTypes(set):
    """A simplified container for managing content types."""
    def __init__(self):
        self._map = FoldedCaseKeyedDict()

    def add(self, content_type):
        self._map[content_type.key] = content_type
        super().add(content_type)

    def find_for(self, name):
        # first search the overrides (by name)
        item = self._map.get(name)
        if item:
            return item
        # then fall back to the defaults (by extension)
        extension = name.split('.')[-1] if '.' in name else name
        return self._map.get('.' + extension, None)


def test_find_for():
    content_types = ContentTypes()
    content_types.add(ContentType("application/xml", ".xml"))
    content_types.add(ContentType("application/vnd.openxmlformats-package.core-properties+xml", "core.xml"))

    ct1 = content_types.find_for("sample.xml")
    assert ct1.name == "application/xml"

    ct2 = content_types.find_for("core.xml")
    assert ct2.name == "application/vnd.openxmlformats-package.core-properties+xml"

    ct3 = content_types.find_for("unknown.xyz")
    assert ct3 == None

if __name__ == "__main__":
    test_find_for()

