import weakref
import inspect

class World(object):
    def __init__(self, peng):
        self.peng = peng
        self.cameras = {}
        self.actors = {}
        self.views = {}
        self.eventHandlers = {}
        self.recvEvents = True

    def addCamera(self, camera):
        if not isinstance(camera, Camera):
            raise TypeError("camera is not of type Camera!")
        self.cameras[camera.name] = camera

    def addView(self, view):
        if not isinstance(view, WorldView):
            raise TypeError("view is not of type WorldView!")
        self.views[view.name] = view

    def addActor(self, actor):
        self.actors[actor.uuid] = actor

    def getView(self, name):
        if name not in self.views:
            raise ValueError("Unknown world view")
        return self.views[name]

    def render3d(self, view=None):
        for actor in self.actors.values():
            actor.render(view)

    def handle_event(self, event_type, args, window=None):
        if not self.recvEvents:
            return
        args = list(args)

        if event_type in self.eventHandlers:
            for whandler in self.eventHandlers[event_type]:
                handler = whandler()
                if handler is None:
                    del self.eventHandlers[event_type][self.eventHandlers[event_type].index(whandler)]
                handler(*args)

    def registerEventHandler(self, event_type, handler):
        if event_type not in self.eventHandlers:
            self.eventHandlers[event_type] = []
        if inspect.ismethod(handler):
            handler = weakref.WeakMethod(handler)
        else:
            handler = weakref.ref(handler)
        self.eventHandlers[event_type].append(handler)

class Camera:
    def __init__(self, name):
        self.name = name

class WorldView:
    def __init__(self, name):
        self.name = name

class Actor:
    def __init__(self, uuid):
        self.uuid = uuid
        # Initialize the call_count attribute
        self.call_count = 0

    def render(self, view):
        # Increment the call_count each time the render method is called
        self.call_count += 1

def test_render3d():
    peng = None
    world = World(peng)
    camera = Camera(name="MainCamera")
    world.addCamera(camera)
    view = WorldView(name="MainView")
    world.addView(view)
    actor = Actor(uuid="actor_1")
    world.addActor(actor)

    actors_calls_before = [actor.call_count for actor in world.actors.values()]
    world.render3d(view)
    actors_calls_after = [actor.call_count for actor in world.actors.values()]

    assert len(actors_calls_before) == len(actors_calls_after)
    assert all(a_after == a_before + 1 for a_before, a_after in zip(actors_calls_before, actors_calls_after))
    assert world.cameras == {camera.name: camera}
    assert world.views == {view.name: view}

if __name__ == "__main__":
    test_render3d()

