class spawn(object):
    def __init__(self):
        self.encoding = "utf-8"

    def _cast_bytes(self, s, enc):
        if isinstance(s, str):
            return s.encode(enc)
        return s

    def _cast_unicode(self, s, enc):
        if isinstance(s, bytes):
            return s.decode(enc)
        return s

    def _prepare_regex_pattern(self, p):
        if isinstance(p.pattern, bytes):
            p = re.compile(p.pattern.decode(self.encoding), p.flags)
        return p

