    assert my_spawn._prepare_regex_pattern(re.compile(b'hello')).pattern == 'hello'
    assert my_spawn._prepare_regex_pattern(re.compile('hello')).pattern == 'hello'
    assert my_spawn._prepare_regex_pattern(re.compile(b'\d+')).pattern == '\\d+'

