# Simplification of the explicit_embed_and_overrides function from the 'python-bidi' package

PARAGRAPH_LEVELS = {'L': 0, 'AL': 1, 'R': 1}
EXPLICIT_LEVEL_LIMIT = 62
X2_X5_MAPPINGS = {
    'RLE': (lambda x: (x + 1) | 1, 'N'),
    'LRE': (lambda x: (x + 2) & ~1, 'N'),
    'RLO': (lambda x: (x + 1) | 1, 'R'),
    'LRO': (lambda x: (x + 2) & ~1, 'L'),
}
X9_REMOVED = list(X2_X5_MAPPINGS.keys()) + ['BN', 'PDF']

def explicit_embed_and_overrides(storage):
    overflow_counter = almost_overflow_counter = 0
    directional_override = 'N'
    levels = []

    embedding_level = storage['base_level']
    for _ch in storage['chars']:
        bidi_type = _ch['type']

        level_func, override = X2_X5_MAPPINGS.get(bidi_type, (None, None))

        if level_func:
            if overflow_counter != 0:
                overflow_counter += 1
                continue

            new_level = level_func(embedding_level)
            if new_level < EXPLICIT_LEVEL_LIMIT:
                levels.append((embedding_level, directional_override))
                embedding_level, directional_override = new_level, override
            elif embedding_level == EXPLICIT_LEVEL_LIMIT - 2:
                almost_overflow_counter += 1
            else:
                overflow_counter += 1
        else:
            if bidi_type not in X9_REMOVED:
                _ch['level'] = embedding_level
                if directional_override != 'N':
                    _ch['type'] = directional_override
            elif bidi_type == 'PDF':
                if overflow_counter:
                    overflow_counter -= 1
                elif almost_overflow_counter:
                    almost_overflow_counter -= 1
                elif levels:
                    embedding_level, directional_override = levels.pop()
            elif bidi_type == 'B':
                levels.clear()
                overflow_counter = almost_overflow_counter = 0
                embedding_level = _ch['level'] = storage['base_level']
                directional_override = 'N'

    storage['chars'] = [_ch for _ch in storage['chars'] if _ch['type'] not in X9_REMOVED]

    # pretend calc_level_runs does something
    storage['runs'] = []

def get_empty_storage():
    return {
        'base_level': None,
        'base_dir': None,
        'chars': [],
        'runs': [],
    }

def test_explicit_embed_and_overrides():
    storage = get_empty_storage()
    storage['base_level'] = 0
    storage['chars'] = [{'ch': 'a', 'level': 0, 'type': 'L', 'orig': 'L'}]
    explicit_embed_and_overrides(storage)
    assert storage['chars'] == [{'ch': 'a', 'level': 0, 'type': 'L', 'orig': 'L'}]

    storage = get_empty_storage()
    storage['base_level'] = 0
    storage['chars'] = [{'ch': 'RLE', 'level': 0, 'type': 'RLE', 'orig': 'RLE'}, {'ch': 'a', 'level': 0, 'type': 'L', 'orig': 'L'}]
    explicit_embed_and_overrides(storage)
    assert storage['chars'] == [{'ch': 'a', 'level': 1, 'type': 'L', 'orig': 'L'}]

    storage = get_empty_storage()
    storage['base_level'] = 1
    storage['chars'] = [{'ch': 'LRO', 'level': 1, 'type': 'LRO', 'orig': 'LRO'}, {'ch': 'a', 'level': 0, 'type': 'R', 'orig': 'R'}]
    explicit_embed_and_overrides(storage)
    assert storage['chars'] == [{'ch': 'a', 'level': 2, 'type': 'L', 'orig': 'R'}]

if __name__ == '__main__':
    test_explicit_embed_and_overrides()

