from botocore.compat import six

if sys.platform.startswith('win'):
    def rename_file(current_filename, new_filename):
        try:
            os.remove(new_filename)
        except OSError as e:
            if not e.errno == errno.ENOENT:
                raise
        os.rename(current_filename, new_filename)
else:
    rename_file = os.rename

if six.PY3:
    def accepts_kwargs(func):
        return inspect.getfullargspec(func)[2]
    SOCKET_ERROR = ConnectionError
    MAXINT = None
else:
    def accepts_kwargs(func):
        return inspect.getargspec(func)[2]
    SOCKET_ERROR = socket.error
    MAXINT = sys.maxint

def seekable(fileobj):
    if hasattr(fileobj, 'seekable'):
        return fileobj.seekable()
    elif hasattr(fileobj, 'seek') and hasattr(fileobj, 'tell'):
        try:
            fileobj.seek(0, 1)
            return True
        except (OSError, IOError):
            return False
    return False

def test_seekable():
    file_path = "test_file.txt"
    with open(file_path, "w") as f:
        f.write("Test content")

    with open(file_path, "r") as f:
        assert seekable(f) == True

    class NonSeekable:
        def __init__(self):
            self.start = 0
        def read(self, size):
            return ""
        def not_seekable(self):
            return False

    non_seekable_obj = NonSeekable()
    assert seekable(non_seekable_obj) == False

    class SeekableWithException:
        def __init__(self):
            self.start = 0
        def seek(self, pos, whence):
            raise OSError("seeking is not supported")
        def tell(self):
            return self.start
        def not_seekable(self):
            return False

    seekable_with_exception = SeekableWithException()
    assert seekable(seekable_with_exception) == False

    os.remove(file_path)

if __name__ == "__main__":
    test_seekable()

