import json
import time
import datetime
from decimal import Decimal


class PostgresToGoogleCloudStorageOperator:

    @classmethod
    def convert_types(cls, value):
        """
        Takes a value from Postgres, and converts it to a value that's safe for
        JSON/Google Cloud Storage/BigQuery. Dates are converted to UTC seconds.
        Decimals are converted to floats. Times are converted to seconds.
        """
        if type(value) in (datetime.datetime, datetime.date):
            return time.mktime(value.timetuple())
        elif type(value) == datetime.time:
            formated_time = time.strptime(str(value), "%H:%M:%S")
            return datetime.timedelta(
                hours=formated_time.tm_hour,
                minutes=formated_time.tm_min,
                seconds=formated_time.tm_sec).seconds
        elif isinstance(value, Decimal):
            return float(value)
        else:
            return value

def test_convert_types():
    # Test datetime conversion
    datetime_val = datetime.datetime.strptime('2022-06-01 13:45:30', '%Y-%m-%d %H:%M:%S')
    datetime_converted = PostgresToGoogleCloudStorageOperator.convert_types(datetime_val)
    assert datetime_converted == time.mktime(datetime_val.timetuple())

    # Test timedelta conversion
    time_val = datetime.datetime.strptime('13:45:30', '%H:%M:%S').time()
    time_converted = PostgresToGoogleCloudStorageOperator.convert_types(time_val)
    seconds = (13 * 3600) + (45 * 60) + 30
    assert time_converted == seconds

    # Test Decimal conversion
    decimal_val = Decimal('72.39')
    decimal_converted = PostgresToGoogleCloudStorageOperator.convert_types(decimal_val)
    assert decimal_converted == float(decimal_val)

if __name__ == '__main__':
    test_convert_types()

