    """Show all institutes in the database"""
    context = DummyContext()
    adapter = context.obj['adapter']

    if institute_id:
        institute_objs = []
        institute_obj = adapter.institute(institute_id)
        if not institute_obj:
            print(f"Institute {institute_id} does not exist")
            return None  # Change here to return None instead of just return
        institute_objs.append(institute_obj)
