import regex as re
import collections

def cleanse(text):
    return re.sub('\W+', ' ', text.lower())

def look_ahead_match(rating, tokens):
    all_mregexes = []
    for m in rating.mentions:
        mregexes = []
        mpatterns = m.decode('utf8').split(' ')
        for mpat in mpatterns:
            if mpat.startswith('ur"^') and mpat.endswith('$"'):
                mpat = mpat[4:-2]
            else:
                mpat = cleanse(mpat)
            if mpat:
                mpat = r'^%s$' % mpat
                mregexes.append(re.compile(mpat, flags=re.UNICODE | re.IGNORECASE))
        all_mregexes.append(mregexes)

    for i in range(len(tokens)):
        for mregexes in all_mregexes:
            if mregexes[0].match(tokens[i][0][0]):
                m_j = 1
                i_j = 0
                last_token_matched = 0
                matched = True
                while m_j < len(mregexes):
                    i_j += 1
                    if i_j == len(tokens[i + last_token_matched][0]):
                        i_j = 0
                        last_token_matched += 1
                        if i + last_token_matched == len(tokens):
                            matched = False
                            break
                    target_token = tokens[i + last_token_matched][0][i_j]
                    if mregexes[m_j].match(target_token):
                        m_j += 1
                    elif target_token == '':
                        continue
                    else:
                        matched = False
                        break
                if matched:
                    toks = set()
                    for j in range(last_token_matched + 1):
                        toks.add(tokens[i + j][1])
                    for tok in toks:
                        yield tok

class Rating:
    def __init__(self, mentions):
        self.mentions = mentions

def test_look_ahead_match():
    tokens = [(['somestring'], 'a_token'), (['anotherstring'], 'another_token')]
    rating = Rating([b'somestring', b'anotherstring'])
    assert list(look_ahead_match(rating, tokens)) == ['a_token', 'another_token']

    tokens = [(['notmatching'], 'no_token'), (['anothernotmatching'], 'no_token_2')]
    rating = Rating([b'somestring', b'anotherstring'])
    assert list(look_ahead_match(rating, tokens)) == []

    tokens = [(['somestring'], 'a_token'), (['anotherstring'], 'another_token')]
    rating = Rating([b'missingstring', b'anothermissingstring'])
    assert list(look_ahead_match(rating, tokens)) == []

if __name__ == '__main__':
    test_look_ahead_match()

