import sys

_logger = logging.getLogger(__name__)

def catch(logger):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception:
                logger.warning(f"Exception raised in decorator: {func.__name__}")
        return wrapper
    return decorator

@catch(_logger)
def _log_time(logger, func_name, start, end):
    duration = (end - start) * 1000
    logger.info(f"{func_name} - time: {duration:0.1f} ms")

def log_time(logger):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start = time.time()
            result = func(*args, **kwargs)
            end = time.time()
            _log_time(logger, func.__name__, start, end)
            return result
        return wrapper
    return decorator

def test_log_time():
    capturer = io.StringIO()
    ch = logging.StreamHandler(capturer)  # Direct log output to capturer instead of sys.stdout
    local_logger = logging.getLogger()
    local_logger.setLevel(logging.INFO)
    local_logger.addHandler(ch)

    @log_time(local_logger)
    def example_function(message):
        time.sleep(0.5)
        return message.upper()

    example_message = "hello world"
    output = example_function(example_message)
    log_content = capturer.getvalue()

    assert "example_function - time:" in log_content
    assert " ms" in log_content
    assert output == "HELLO WORLD"

    # Clean up by removing the handler
    local_logger.removeHandler(ch)
    ch.close()

if __name__ == "__main__":
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    ch = logging.StreamHandler()
    logger.addHandler(ch)

    @log_time(logger)
