import collections
from pyrser.parsing.stream import Stream
from pyrser.parsing.node import Node

# Since we cannot test the code with unavailable libraries (pyrser), 
# the following test example assumes that the environment has the required packages installed.

class Diagnostic:
    def notify(self, severity, message, location_info):
        print(f"{severity}: {message} at {location_info}")

class BasicParser:
    _rules = collections.ChainMap()
    _hooks = collections.ChainMap()

    def __init__(self, content: str = '', stream_name: str = None, raise_diagnostic=True):
        self._streams = [Stream(content, stream_name)]
        self.rule_nodes = None
        self.push_rule_nodes()
        self.diagnostic = Diagnostic()

    def push_rule_nodes(self):
        if self.rule_nodes is None:
            self.rule_nodes = collections.ChainMap()
        else:
            self.rule_nodes = self.rule_nodes.new_child()

    def pop_rule_nodes(self):
        self.rule_nodes = self.rule_nodes.parents

    def value(self, node: Node) -> str:
        if isinstance(node, Node):
            return node.value
        return ""

    def eval_rule(self, name: str):
        n = Node()
        self.rule_nodes['_'] = n
        if name not in self._rules:
            self.diagnostic.notify("ERROR", "Unknown rule", None)
            raise Exception("Unknown rule")
        return self._rules[name](self)

    def begin_tag(self, name: str):
        self.rule_nodes[name] = Node()

    def end_tag(self, name: str):
        node = self.rule_nodes.get(name)
        if node:
            node.close()

    def tag_node(self, name: str, node: Node):
        self.rule_nodes[name] = node

class Node:
    def __init__(self):
        self.value = ""
        self.closed = False

    def close(self):
        self.closed = True

def bind(parser: BasicParser, dst: str, src: Node) -> bool:
    for m in parser.rule_nodes.maps:
        for k, v in m.items():
            if k == dst:
                m[k] = src
                return True
    raise Exception('%s not found' % dst)

def test_bind():
    p = BasicParser(content="test")
    n1 = Node()
    n1.value = "nodeValue1"
    n2 = Node()
    n2.value = "nodeValue2"
    p.begin_tag("tag1")
    p.begin_tag("tag2")
    p.tag_node("tag1", n1)
    p.tag_node("tag2", n2)

    assert bind(p, "tag1", n2) == True
    assert p.rule_nodes["tag1"].value == "nodeValue2"
    assert p.rule_nodes["tag2"].value == "nodeValue2"

if __name__ == '__main__':
    test_bind()

