import sys
from datetime import datetime
import six
from requests import HTTPError, Response


class ShortenedURL(object):
    def __init__(self, shorturl, url, title, date, ip, clicks, keyword=None):
        self.shorturl = shorturl
        self.url = url
        self.title = title
        self.date = date
        self.ip = ip
        self.clicks = clicks
        self.keyword = keyword

def _validate_yourls_response(response, data):
    """Validate response from YOURLS server."""
    try:
        response.raise_for_status()
    except HTTPError as http_exc:
        http_error_info = sys.exc_info()
        reraise = False

        try:
            jsondata = response.json()
        except ValueError:
            reraise = True

        if reraise:
            six.reraise(*http_error_info)
    else:
        jsondata = response.json()

        if {'status', 'code', 'message'} <= set(jsondata.keys()):
            status = jsondata['status']
            code = jsondata['code']
            message = jsondata['message']

            if status == 'fail':
                if code == 'error:keyword':
                    raise ValueError(f"YOURLSKeywordExistsError: {message}, keyword: {data['keyword']}")
                elif code == 'error:url':
                    url = _json_to_shortened_url(jsondata['url'], jsondata['shorturl'])
                    raise ValueError(f"YOURLSURLExistsError: {message}, url: {url}")
                else:
                    raise ValueError(f"YOURLSAPIError: {message}")
            else:
                return jsondata
        else:
            return jsondata

def _json_to_shortened_url(urldata, shorturl=None):
    if shorturl is None:
        shorturl = urldata['shorturl']

    if 'date' in urldata:
        date = urldata['date']
    elif 'timestamp' in urldata:
        date = urldata['timestamp']
    else:
        raise ValueError("Expected 'date' or 'timestamp' key in JSON response.")

    keyword = urldata.get('keyword', None)
    clicks = int(urldata.get('clicks', '0'))

    url = ShortenedURL(
        shorturl=shorturl,
        url=urldata['url'],
        title=urldata['title'],
        date=datetime.strptime(date, '%Y-%m-%d %H:%M:%S'),
        ip=urldata['ip'],
        clicks=clicks,
        keyword=keyword)
    return url

def test__validate_yourls_response():
    response1 = Response()
    response1.status_code = 200
    response1._content = b'{"status": "success", "shorturl": "http://example.com/1", "url": "http://original-url/1", "title": "Test", "date": "2022-01-01 00:00:00", "ip": "0.0.0.0", "clicks": "10", "keyword": "test1"}'

    response2 = Response()
    response2.status_code = 400
    response2._content = b'{"status": "fail", "code": "error:keyword", "message": "Keyword already exists", "keyword": "test1"}'

    response3 = Response()
    response3.status_code = 400
    response3._content = b'{"status": "fail", "code": "error:url", "message": "URL already exists", "url": {"shorturl": "http://example.com/1", "url": "http://original-url/1", "title": "Test", "date": "2022-01-01 00:00:00", "ip": "0.0.0.0", "clicks": "10", "keyword": "test1"}}'

    assert _validate_yourls_response(response1, {'keyword': 'test1'}) == response1.json()

    try:
        _validate_yourls_response(response2, {'keyword': 'test1'})
    except ValueError as ve:
        assert str(ve) == 'YOURLSKeywordExistsError: Keyword already exists, keyword: test1'

    try:
        _validate_yourls_response(response3, {'keyword': 'test1'})
    except ValueError as ve:
        assert str(ve).startswith('YOURLSURLExistsError')

if __name__ == '__main__':
    test__validate_yourls_response()

