    assert manager.get(request=request2, pk=2) == {"parent": 2, "head": True, "revision_id": 3, "preview_id": "def456"}
    assert manager.get(request=request3, pk=3) == {"parent": 3, "head": True}

def main():
    test_get()

if __name__ == "__main__":
    main()

