        return self.enabled

    def disable(self):
        self.enabled = False
        return self.enabled

    pass  # end of Breakpoint class

def test_en_disable_breakpoint_by_number():
    bpmgr = BreakpointManager()
    breakpoint1 = Breakpoint(1, 'foo.py', 5)
    bpmgr.bpbynumber.append(breakpoint1)

    success, msg = bpmgr.en_disable_breakpoint_by_number(1, do_enable=False)
