class GraphNode:
    """ Defines a representation of a graph node for use by the graph editor
        and the graph editor factory classes.
    """

    def __init__(self, label="", formatter=None):
        self.label = label
        self.formatter = formatter

    def get_label(self, object):
        """ Gets the label to display for a specified object.
        """
        label = self.label
        if label[:1] == "=":
            return label[1:]

        label = getattr(object, label, "")

        if self.formatter is None:
            return label

        return self.formatter(object, label)

