    node = GraphNode(label="name")
    obj = type("TestObject", (object,), {"name": "John"})
    assert node.get_label(obj) == "John"

    node2 = GraphNode(label="=ConstantLabel")
    assert node2.get_label(obj) == "ConstantLabel"

    def formatter(obj, label):
        return f"Formatted {label}"

    node3 = GraphNode(label="location", formatter=formatter)
    obj = type("TestObject", (object,), {"location": "New York"})
    assert node3.get_label(obj) == "Formatted New York"

