class FakeModel:
    pass

class Permission(FakeModel):
    DoesNotExist = ImproperlyConfigured
    objects = type('Manager', (), {'get': lambda self, codename, content_type__app_label: Permission()})()

class settings:
    MODEL_TREE = 'app.Tree'
    MODEL_TREE_ITEM = 'app.TreeItem'

def apps_get_model(app_name, model_name):
    if f"{app_name}.{model_name}" == settings.MODEL_TREE:
        return type('Tree', (FakeModel,), {})
    if f"{app_name}.{model_name}" == settings.MODEL_TREE_ITEM:
        return type('TreeItem', (FakeModel,), {})
    return None

def get_model_class(settings_entry_name):
    try:
        app_name, model_name = getattr(settings, settings_entry_name).split('.')
    except AttributeError:
        raise ImproperlyConfigured(
            '`SITETREE_%s` refers to model `%s` that has not been installed.' % (settings_entry_name, 'MISSING'))
    except ValueError:
        raise ImproperlyConfigured(
            '`SITETREE_%s` must have the following format: `app_name.model_name`.' % settings_entry_name)
    model = apps_get_model(app_name, model_name)
    if model is None:
        raise ImproperlyConfigured(
            '`SITETREE_%s` refers to model `%s` that has not been installed.' % (settings_entry_name, model_name))
    return model

# Test function
def test_get_model_class():
    assert get_model_class("MODEL_TREE").__name__ == "Tree"
    assert get_model_class("MODEL_TREE_ITEM").__name__ == "TreeItem"

    # Test wrong setting
    try:
        get_model_class("MODEL_WRONG_SETTING")
    except ImproperlyConfigured as e:
        assert str(e) == '`SITETREE_MODEL_WRONG_SETTING` refers to model `MISSING` that has not been installed.'

    # Test wrong format
    try:
        settings.MODEL_WRONG_FORMAT = 'WrongString'
        get_model_class("MODEL_WRONG_FORMAT")
    except ImproperlyConfigured as e:
        assert str(e) == ('`SITETREE_MODEL_WRONG_FORMAT` must have the '
                          'following format: `app_name.model_name`.')

# Run the tests
if __name__ == '__main__':
    test_get_model_class()

