import json

# Mock websocket client to mimic a simple WebSocket for demonstration purposes.
class MockWebSocket:
    def write_message(self, message):
        print(f"WebSocket received message: {message}")

# Thing class implementation, simplified and using MockWebSocket.
class Thing:
    """A Web Thing."""

    def __init__(self, name, type_=[], description=''):
        if not isinstance(type_, list):
            type_ = [type_]

        self.context = 'https://iot.mozilla.org/schemas'
        self.type = type_
        self.name = name
        self.description = description
        self.available_events = {}
        self.events = []
        self.subscribers = set()

    def add_event_subscriber(self, name, ws):
        """
        Add a new websocket subscriber to an event.

        name -- name of the event
        ws -- the websocket
        """
        if name in self.available_events:
            self.available_events[name]['subscribers'].add(ws)

    def add_available_event(self, name, metadata=None):
        """
        Add an available event.

        name -- name of the event
        metadata -- event metadata, i.e. type, description, etc., as a dict
        """
        if metadata is None:
            metadata = {}

        self.available_events[name] = {
            'metadata': metadata,
            'subscribers': set(),
        }

    def event_notify(self, event_name, event_data):
        """
        Notify all subscribers of an event.

        event_name -- the name of the event
        event_data -- the event data to be sent
        """
        if event_name not in self.available_events:
            return

        message = json.dumps({
            'messageType': 'event',
            'data': {
                'name': event_name,
                'data': event_data,
            }
        })

        subscribers = self.available_events[event_name]['subscribers']
        for subscriber in subscribers:
            try:
                subscriber.write_message(message)
            except Exception as e:
                print(f"WebSocket error: {e}")

