    thing.add_available_event("TestEvent")

    # Subscribing our mock websocket to the "TestEvent"
    thing.add_event_subscriber("TestEvent", ws1)

    assert ws1 in thing.available_events["TestEvent"]["subscribers"]

    # Subscribing another mock websocket to the "TestEvent"
    thing.add_event_subscriber("TestEvent", ws2)

