class ModelBase:
    """Base class for all models."""

    def __init__(self):
        """Construct a new model instance."""
        self._id = None
        self.parms = {}  

    @property
    def model_id(self):
        """Model identifier."""
        return self._id

    @model_id.setter
    def model_id(self, newid):
        oldid = self._id
        self._id = newid

    @property
    def params(self):
        """
        Get the parameters and the actual/default values only.

        :returns: A dictionary of parameters used to build this model.
        """
        params = {}
        for p in self.parms:
            params[p] = {"default": self.parms[p]["default_value"],
                         "actual": self.parms[p]["actual_value"]}
        return params

    def coef(self):
        tbl = self._model_json["output"]["coefficients_table"]
        if tbl is None: return None

        return {name: coef for name, coef in zip(tbl["names"], tbl["coefficients"])}

def test_coef():
    model = ModelBase()
    model._model_json = {"output": {"coefficients_table": {"names": ["A", "B"], "coefficients": [1, 2]}}}
    assert model.coef() == {"A": 1, "B": 2}

    model._model_json = {"output": {"coefficients_table": {"names": [], "coefficients": []}}}
    assert model.coef() == {}

    model._model_json = {"output": {"coefficients_table": None}}
    assert model.coef() is None

if __name__=='__main__':
    test_coef()

