from collections import deque
from fractions import Fraction
from datetime import datetime
import re
from typing import List, Optional, Dict, Any, Tuple, Union

class Comment:
    pass

class SyntaxError(Exception):
    pass

def _inst_from_str(inst_str: str) -> datetime:
    try:
        return datetime.strptime(inst_str, '%Y-%m-%d %H:%M:%S')
    except (ValueError, OverflowError):
        raise SyntaxError(f"Unrecognized date/time syntax: {inst_str}")

class StreamReader:
    DEFAULT_INDEX = 0

    def __init__(self, stream: str):
        self._stream = stream
        self._idx = self.DEFAULT_INDEX
        self._buffer = deque(stream)

    def pushback(self) -> None:
        if self._idx >= 0:
            self._idx -= 1

    def peek(self) -> str:
        if self._idx < self.DEFAULT_INDEX:
            return self._buffer[0]
        else:
            return self._buffer[self._idx + 1]

    def next_token(self) -> str:
        if self._idx < len(self._buffer):
            token = self._buffer[self._idx]  # Get the current character
            self._idx += 1
            return token
        else:
            return ''  # Return an empty string when the end of the stream is reached.

class ReaderContext:
    def __init__(self, reader: StreamReader):
        self._reader = reader

    @property
    def reader(self) -> StreamReader:
        return self._reader

_WHITESPACE_CHARS = re.compile(" ")
_READER_MACRO = re.compile("#''")

def _read_next(ctx: ReaderContext) -> str:
    reader = ctx.reader
    token = ""
    while True:
        token += reader.peek()
        reader.next_token()

        if _WHITESPACE_CHARS.match(reader.peek()):
            break

    if _READER_MACRO.match(token):
        return Comment()

    return token

def read(stream: str) -> Tuple:
    reader = StreamReader(stream)
    ctx = ReaderContext(reader)
    result = []

    while reader.peek():
        next_value = _read_next(ctx)
        if not isinstance(next_value, Comment):
            result.append(next_value)

    return tuple(result)

def test_next_token():
    sr = StreamReader("hello world")
    assert sr.next_token() == "h"
    assert sr.next_token() == "e"
