class Task:
    _the_callable = None  # Class level attribute to store the callable

    def __init__(self):
        self._func_info = '{}'

    @property
    def funcinfo(self):
        return json.loads(self._func_info)

    @funcinfo.setter
    def funcinfo(self, data):
        self._func_info = json.dumps(data)

    @classmethod
    def run_once(cls, the_callable, userdata=None, delay_until=None):
        """Class method to run a one-shot task, immediately."""
        if the_callable is None:
            raise ValueError("The callable provided is None")
        if not callable(the_callable):
            raise ValueError(f"{the_callable} is not a callable object")
        cls._the_callable = the_callable  # Store the reference to the callable
        cls.run_iterations(cls._the_callable, userdata=userdata, run_immediately=True, delay_until=delay_until)

    def func_from_info(self):
        return Task._the_callable  # Return the stored callable reference

    @staticmethod
    def run_iterations(the_callable, userdata=None, run_immediately=False, delay_until=None):
        task = Task()
        task.funcinfo = get_func_info(the_callable)

        if run_immediately:
            task.execute()

    def execute(self):
        the_callable = self.func_from_info()
        the_callable()

