    if inspect.isfunction(thing):
        return dict(
            func_type='function',
            module_name=thing.__module__,
            func_name=thing.__name__,
            func_path=f"{thing.__module__}.{thing.__name__}",
        )
    else:
        raise ValueError(f"{thing} is not a callable object")

