    import io
    import sys

    # Example function that should be executed by Task.run_once
    def example_function():
        print("Running the example function!")

    # Store the original stdout to restore it later
    original_stdout = sys.stdout

    # Redirect stdout to an io.StringIO buffer to capture print() output
    sys.stdout = io.StringIO()

    # Call the run_once method on the Task class with the example_function as the argument
    Task.run_once(example_function)

    # Check if the example function print output is captured correctly
    assert sys.stdout.getvalue() == "Running the example function!\n"

    # Test the execution with None
    try:
        Task.run_once(None)
        assert False, "Should raise ValueError"
    except ValueError:
        assert True

    # Test the execution with a non-callable object
    try:
        Task.run_once("Non-callable")
        assert False, "Should raise ValueError"
    except ValueError:
        assert True

    # Restore the original stdout
    sys.stdout = original_stdout

if __name__=='__main__':
    test_run_once()

