    middleware_set_with_another_middleware = middleware_set.use(anonymous_middleware)
    assert middleware_set_with_another_middleware._middleware == [anonymous_middleware, anonymous_middleware]

    try:
        middleware_set.use("invalid middleware")
    except TypeError as e:
        assert str(e) == 'MiddlewareSet.use(): invalid middleware at index "0" being added.'

