                          "proxy", "auth", "cookies", "verbose"]

    def __init__(self, config=None):
        self._ip = None
        self._port = None
        self._https = None
        self._context_path = ''
        self._verify_ssl_certificates = True
        self._proxy = None
        self._auth = None
        self._cookies = None
        self._verbose = True
        if config is not None:
            self._fill_from_config(config)

    def _fill_from_config(self, config):
        for k, v in config.items():
            if k in self.allowed_properties:
                setattr(self, f'_{k}', v)  # Prepend the underscore to attribute names
            else:
                raise ValueError("Unsupported name of property: %s!" % k)

