def balance_chunk ( chunk ) :
    chunk_size = len ( chunk )
    chunk_sum = sum ( chunk )
    while chunk_sum > 0 :
        chunk_sum -= 1
        for j in range ( chunk_size ) :
            if chunk [ j ] > - 13 :
                chunk [ j ] -= 1
                break
    while chunk_sum < 0 :
        chunk_sum += 1
        for j in range ( chunk_size ) :
            if chunk [ j ] < 13 :
                chunk [ j ] += 1
                break
    return chunk

