from functools import wraps

class User:
    def __init__(self, is_superuser, groups, is_authenticated=True):
        self.is_superuser = is_superuser
        self.groups = groups
        self.is_authenticated = is_authenticated

class Group:
    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return f"Group(name='{self.name}')"

class Request:
    def __init__(self, user):
        self.user = user

def login_required(redirect_field_name=None, login_url=None):
    def decorator(view_func):
        @wraps(view_func)
        def _wrapped_view(request, *args, **kwargs):
            if request.user.is_authenticated:
                return view_func(request, *args, **kwargs)
            return 'User is not authenticated.'

        return _wrapped_view

    return decorator

def group_required(group,
                   login_url=None,
                   redirect_field_name=None,
                   skip_superuser=True):

    def decorator(view_func):
        @login_required(redirect_field_name=redirect_field_name,
                        login_url=login_url)
        def _wrapped_view(request, *args, **kwargs):

            if not (request.user.is_superuser and skip_superuser):
                if group.name not in [req_group.name for req_group in request.user.groups]:
                    return 'Permission Denied'

            return view_func(request, *args, **kwargs)
        return _wrapped_view

    return decorator

