import threading
import weakref

class ClassProperty:
    '''
    Borrowed from: https://gist.github.com/josiahcarlson/1561563
    '''
    def __init__(self, get, set=None, delete=None):
        self.get = get
        self.set = set
        self.delete = delete

    def __get__(self, obj, cls=None):
        if cls is None:
            cls = type(obj)
        return self.get(cls)

    def __set__(self, obj, value):
        cls = type(obj)
        self.set(cls, value)

    def __delete__(self, obj):
        cls = type(obj)
        self.delete(cls)

    def getter(self, get):
        return ClassProperty(get, self.set, self.delete)

    def setter(self, set):
        return ClassProperty(self.get, set, self.delete)

    def deleter(self, delete):
        return ClassProperty(self.get, self.set, delete)

class Session(threading.local):
    '''
    This is a very dumb session. All it tries to do is to keep a cache of
    loaded entities, offering the ability to call .save() on modified (or
    all) entities with .flush() or .commit().
    '''

    def __init__(self, *args, **kwargs):
        threading.local.__init__(self, *args, **kwargs)
        self._init()

    def _init(self):
        try:
            self.known
        except AttributeError:
            self.known = {}
            self.wknown = weakref.WeakValueDictionary()

    @ClassProperty
    def null_session(cls):
        return getattr(cls, '_null_session', None)

    @null_session.setter
    def null_session(cls, value):
        cls._null_session = value

    @null_session.deleter
    def null_session(cls):
        delattr(cls, '_null_session', None)

    def commit(self, full=False, all=False, force=False):
        '''
        Call .save() on all modified entities in the session. Also forgets
        all known entities in the session, so this should only be called at
        the end of a request.
        Arguments:
            * *full* - pass True to force save full entities, not only changes
            * *all* - pass True to save all entities known, not only those entities that have been modified.
            * *force* - pass True to force-save all entities known, ignoring DataRaceError and EntityDeletedError exceptions
        '''
        # Call the static method on the class itself
        changes = self.__class__.flush(full, all, force)
        self.known = {}
        return changes

# Mock flush function for testing purposes
@staticmethod
def mock_flush(full=False, all=False, force=False):  # Modified to staticmethod
    if all:
        return "all_saved"
    elif force:
        return "force_saved"
    elif full:
        return "full_saved"
    else:
        return "default_saved"

# Replace the original flush function with the mock function
Session.flush = mock_flush

# global session object which will be used for testing 'commit' function
session = Session()

def test_commit():
    assert session.commit() == "default_saved"
    assert session.commit(full=True) == "full_saved"
    assert session.commit(all=True) == "all_saved"

if __name__ == '__main__':
    test_commit()

