import pandas as pd
from numpy import nan

def fillna(df, column: str, value=None,  column_value=None):
    if column not in df.columns:
        df[column] = nan

    if value is not None and column_value is not None:
        raise ValueError('You cannot set both the parameters value and column_value')

    if value is not None:
        df[column] = df[column].fillna(value)

    if column_value is not None:
        if column_value not in df.columns:
            raise ValueError(f'"{column_value}" is not a valid column name')
        df[column] = df[column].fillna(df[column_value])

    return df

def test_fillna():
    # Test data
    data = {'variable': ['toto', 'toto', 'toto'],
            'wave': ['wave 1', 'wave 1', 'wave 1'],
            'year': [2014, 2015, 2016],
            'my_value': [300, None, 450]}
    df = pd.DataFrame(data)
    df_filled = fillna(df, 'my_value', value=0)
    assert df_filled.iloc[1, 3] == 0

    new_data = {'value': [1, 2, 3]}
    df2 = df.assign(**new_data)
    df_filled2 = fillna(df2, 'my_value', column_value='value')
    assert df_filled2.iloc[1, 4] == 2

    with_new_column = fillna(df, 'non_existent_column', value=0)
    assert 'non_existent_column' in with_new_column.columns

if __name__ == '__main__':
    test_fillna()

