    text = "This is a test sentence. I love the way this code works. It will surely be helpful."
    data = parse_data(text)
    generator = MarkovGenerator()
    generator.add_chain("test_chain", 2)
    generator.build_chain(data, generator.chains["test_chain"])

    assert len(generator.chains["test_chain"].content) > 0
    assert ('This', 'is') in generator.chains["test_chain"].content.keys()
    assert generator.chains["test_chain"].content[('is', 'a')]["test"] == 1

if __name__ == "__main__":
    test_build_chain()

