def ask_yes_no(prompt, default=None):
    """Asks a question and returns a boolean (y/n) answer.

    If default is given (one of 'y','n'), it is used if the user input is
    empty. Otherwise the question is repeated until an answer is given.

    Valid answers are: y/yes/n/no (match is not case sensitive)."""

    answers = {'y': True, 'n': False, 'yes': True, 'no': False}
    ans = None
    while ans not in answers.keys():
        try:
            ans = input(prompt + ' ').lower()
            if not ans:  # response was an empty string
                if default and default in answers.keys():
                    return answers[default]
                else:
                    continue
        except KeyboardInterrupt:
            pass
        except EOFError:
            if default and default in answers.keys():
                ans = default
                print()
                break
            else:
                raise

    return answers[ans]

def test_ask_yes_no():
    # This function is intended to interact with the user, so we cannot test it
    # directly. Instead, we can test a modified version that does not require
    # user interaction. The modified version takes a user_input parameter which
    # mocks the user input.
    def _ask_yes_no(prompt, user_input, default=None):
        answers = {'y': True, 'n': False, 'yes': True, 'no': False}
        ans = user_input.lower()
        if not ans:
            ans = default
        return answers.get(ans)

    assert _ask_yes_no("Continue?", "y", default="n") == True
    assert _ask_yes_no("Continue?", "yes", default="n") == True
    assert _ask_yes_no("Continue?", "", default="n") == False

