            self.optimizer = None

    def init_optimizer(self, optimizer):
        if isinstance(optimizer, dict):
            optimizer_type = getattr(torch.optim, optimizer['type'])
            optimizer_args = {k: v for k, v in optimizer.items() if k != 'type'}
            optimizer = optimizer_type(self.model.parameters(), **optimizer_args)
        elif not isinstance(optimizer, torch.optim.Optimizer):
            raise TypeError("optimizer must be either an Optimizer object or a dict, but got {}".format(type(optimizer)))
