        id = "invalid-widget"
        template = "widgets/invalid_widget.html"
        zones = ["zone-1"]

    class InvalidTemplateExample:
        id = "invalid-widget"
        name = "Invalid Widget"
        zones = ["zone-1"]

    valid_widget = ValidWidgetExample()
    invalid_name_widget = InvalidNameExample()
    invalid_template_widget = InvalidTemplateExample()

    try:
        validate_widget(valid_widget)
    except InvalidWidget:
        assert False, "Valid widget should not raise an InvalidWidget exception"

    try:
        validate_widget(invalid_name_widget)
        assert False, "Invalid widget name should raise an InvalidWidget exception"
    except InvalidWidget:
        pass

    try:
        validate_widget(invalid_template_widget)
        assert False, "Invalid widget template should raise an InvalidWidget exception"
    except InvalidWidget:
        pass

if __name__ == "__main__":
    test_validate_widget()
