class MockLdapConnection:
    def __init__(self, user, password):
        self.user = user
        self.password = password
        self.bound = False
        self.response = []

    def bind(self):
        if self.user == "valid_user" and self.password == "valid_password":
            self.bound = True
            return True
        else:
            raise ldap3.core.exceptions.LDAPInvalidCredentialsResult

    def unbind(self):
        self.bound = False

    def search(self, *args, **kwargs):
        if self.bound and self.user == "valid_user":
            self.response = [{
                'dn': "cn=valid_user,ou=users,dc=example,dc=com",
                'attributes': {'uid': self.user, 'mail': 'valid_user@example.com'}
            }]
            return True
        else:
            self.response = []

class LDAP3LoginManager:
    def __init__(self):
        self.config = {
            'LDAP_BIND_DIRECT_PREFIX': '',
            'LDAP_BIND_DIRECT_SUFFIX': '',
            'LDAP_BIND_DIRECT_GET_USER_INFO': True,
            'LDAP_USER_OBJECT_FILTER': '(objectclass=person)',
            'LDAP_USER_LOGIN_ATTR': 'uid',
            'LDAP_USER_SEARCH_SCOPE': 'LEVEL',
            'LDAP_GET_USER_ATTRIBUTES': ['uid', 'mail'],
            'LDAP_BIND_DIRECT_CREDENTIALS': True,
            'LDAP_FAIL_AUTH_ON_MULTIPLE_FOUND': False
        }

    def authenticate_direct_credentials(self, username, password):
        bind_user = '{}{}{}'.format(
            self.config.get('LDAP_BIND_DIRECT_PREFIX'),
            username,
            self.config.get('LDAP_BIND_DIRECT_SUFFIX')
        )
        # Changed the keyword argument from bind_user=bind_user to user=bind_user
        connection = MockLdapConnection(user=bind_user, password=password)

        response = AuthenticationResponse()
        try:
            connection.bind()
            response.status = AuthenticationResponseStatus.success
            response.user_id = username

            if self.config.get('LDAP_BIND_DIRECT_GET_USER_INFO'):
                user_filter = '({search_attr}={username})'.format(
                    search_attr=self.config.get('LDAP_USER_LOGIN_ATTR'),
                    username=username
                )
                search_filter = '(&{0}{1})'.format(
                    self.config.get('LDAP_USER_OBJECT_FILTER'),
                    user_filter,
                )

                connection.search(
                    search_base="dc=example,dc=com",
                    search_filter=search_filter,
                    search_scope=ldap3.LEVEL,
                    attributes=self.config.get('LDAP_GET_USER_ATTRIBUTES'),
                )

                if len(connection.response) == 1:
                    user = connection.response[0]
                    user['attributes']['dn'] = user['dn']
                    response.user_info = user['attributes']
                    response.user_dn = user['dn']
                elif self.config.get('LDAP_FAIL_AUTH_ON_MULTIPLE_FOUND') and len(connection.response) > 1:
                    response.status = AuthenticationResponseStatus.fail
        except ldap3.core.exceptions.LDAPInvalidCredentialsResult:
            response.status = AuthenticationResponseStatus.fail

        return response

def test_authenticate_direct_credentials():
    ldap_manager = LDAP3LoginManager()

    # Test with valid credentials
    response = ldap_manager.authenticate_direct_credentials("valid_user", "valid_password")
    assert response.status == AuthenticationResponseStatus.success
    assert response.user_dn == "cn=valid_user,ou=users,dc=example,dc=com"
    assert response.user_info == {'uid': 'valid_user', 'mail': 'valid_user@example.com', 'dn': 'cn=valid_user,ou=users,dc=example,dc=com'}

    # Test with invalid credentials
    response = ldap_manager.authenticate_direct_credentials("invalid_user", "invalid_password")
    assert response.status == AuthenticationResponseStatus.fail

    # Test with empty credentials
    response = ldap_manager.authenticate_direct_credentials("", "")
    assert response.status == AuthenticationResponseStatus.fail

