import os
import re

SEPARATORS = os.sep if os.altsep is None else os.sep + os.altsep

def _translate_glob(pat):
    """Translate a glob pattern to a regular expression."""
    i, n = 0, len(pat)
    res = ''
    while i < n:
        c = pat[i]
        i += 1
        if c == '*':
            res = res + '.*'
        elif c == '?':
            res = res + '.'
        elif c == '[':
            j = i
            if j < n and pat[j] == '!':
                j += 1
            if j < n and pat[j] == ']':
                j += 1
            while j < n and pat[j] != ']':
                j += 1
            if j >= n:
                res = res + '\\['
            else:
                stuff = pat[i:j].replace('\\', '\\\\')
                i = j + 1
                if stuff[0] == '!':
                    stuff = '^' + stuff[1:]
                elif stuff[0] == '^':
                    stuff = '\\' + stuff
                res = '%s[%s]' % (res, stuff)
        else:
            res = res + re.escape(c)
    return res + '\Z(?ms)'

def _compile_pattern(pat, ignore_case=True):
    """Translate and compile a glob pattern to a regular expression matcher."""
    if isinstance(pat, bytes):
        pat_str = pat.decode('ISO-8859-1')
        res_str = _translate_glob(pat_str)
        res = res_str.encode('ISO-8859-1')
    else:
        res = _translate_glob(pat)
    flags = re.IGNORECASE if ignore_case else 0
    return re.compile(res, flags=flags).match

def test__compile_pattern():
    pattern1 = "*.txt"
    matcher1 = _compile_pattern(pattern1)
    assert matcher1("test.txt") is not None
    assert matcher1("test.doc") is None

    pattern2 = "file?.*"
    matcher2 = _compile_pattern(pattern2)
    assert matcher2("file1.txt") is not None
    assert matcher2("fileA.pdf") is not None
    assert matcher2("file11.txt") is None

if __name__ == '__main__':
    test__compile_pattern()

