    """
    This class manages service deployments.
    """

    def __init__(self, subscription_id=None, cert_file=None,
                 host='management.core.windows.net', request_session=None,
                 timeout=30):
        self.subscription_id = subscription_id
        self.cert_file = cert_file
        self.host = host
        self.request_session = request_session
        self.timeout = timeout

    def get_service_certificate(self, service_name, thumbalgorithm, thumbprint):
        '''
        Returns the public data for the specified X.509 certificate associated
        with a hosted service.

        service_name:
            Name of the hosted service.
        thumbalgorithm:
            The algorithm for the certificate's thumbprint.
        thumbprint:
            The hexadecimal representation of the thumbprint.
        '''
        self._validate_not_none('service_name', service_name)
        self._validate_not_none('thumbalgorithm', thumbalgorithm)
        self._validate_not_none('thumbprint', thumbprint)

        # Check if the service exists
        if service_name not in self._get_mock_services():
            raise ValueError("Service not found.")

        # Get certificate from our mock store
        certificate = self._get_mock_certificate(
            service_name,
            thumbalgorithm,
            thumbprint
        )

        if certificate:
            return certificate
        else:
            raise ValueError("Certificate not found.")

    def _validate_not_none(self, param_name, param):
        if param is None:
            raise ValueError("Parameter {} cannot be None.".format(param_name))

    @staticmethod
    def _get_mock_services():
        # Simulate a store of services
        return {
