        if self.board[y][x] == ' ':
            new_board = [list(row) for row in self.board]
            new_board[y][x] = self.player
            return Board.from_board(tuple(tuple(row) for row in new_board))
        return self

    @classmethod
    def from_board(cls, board):
        new_instance = cls.__new__(cls)
        new_instance.board = board
        return new_instance

