from collections import Hashable

class ExpectationNotMet(Exception):
    pass

def predicate(func):
    def wrapper(*args, **kwargs):
        if "wait" not in kwargs:
            kwargs["wait"] = 0
        try:
            return func(*args, **kwargs)
        except ExpectationNotMet:
            return False
    return wrapper

class MatchersMixin(object):
    @predicate
    def has_selector(self, *args, **kwargs):
        return self.assert_selector(*args, **kwargs)

    @predicate
    def has_no_selector(self, *args, **kwargs):
        return self.assert_no_selector(*args, **kwargs)

    def assert_selector(self, *args, **kwargs):
        if kwargs.get("count", 1) < 1:
            raise ExpectationNotMet(f"Count {kwargs['count']} is less than 1")
        return True

    def assert_no_selector(self, *args, **kwargs):
        if kwargs.get("count", 1) < 1:
            return True
        raise ExpectationNotMet(f"Count {kwargs['count']} is greater than 0")

    @predicate
    def has_none_of_selectors(self, selector, *locators, **kwargs):
        if not isinstance(selector, Hashable):
            locators = (selector,) + locators
            selector = 'default'
        for locator in locators:
            if not self.has_no_selector(selector, locator, **kwargs):
                return False
        return True

def test_has_none_of_selectors():
    class DummyNode(MatchersMixin):
        pass

    node = DummyNode()
    assert node.has_none_of_selectors('a', 'b', count=0) == True
    assert node.has_none_of_selectors('a', 'b', count=1) == False
    assert node.has_none_of_selectors('a', count=0, wait=1) == True

if __name__ == '__main__':
    test_has_none_of_selectors()

