        # Add internal storage for tiers and annotations
        self.tiers = {}
        self.annotations = {}

    def add_tier(self, tier_name, *args, **kwargs):
        self.tiers[tier_name] = {}

    def get_tier_names(self):
        return list(self.tiers.keys())

    def remove_tier(self, tier_name):
        del self.tiers[tier_name]
        del self.annotations[tier_name]

    def get_parameters_for_tier(self, tier_name):
        return self.tiers.get(tier_name, dict(LINGUISTIC_TYPE_REF=None, PARENT_REF=None, 
                    DEFAULT_LOCALE=None, PARTICIPANT=None, ANNOTATOR=None))

    def add_annotation(self, tier_name, start_time, end_time, value):
        if tier_name not in self.annotations:
            self.annotations[tier_name] = []
        self.annotations[tier_name].append((start_time, end_time, value))

    def get_annotation_data_for_tier(self, tier_name):
        return self.annotations.get(tier_name, [])

    def copy_tier(self, eaf_obj, tier_name):
        if tier_name in eaf_obj.get_tier_names():
            eaf_obj.remove_tier(tier_name)

        tier_params = self.get_parameters_for_tier(tier_name)
        eaf_obj.add_tier(tier_name, **tier_params)

        for ann in self.get_annotation_data_for_tier(tier_name):
            eaf_obj.add_annotation(tier_name, ann[0], ann[1], ann[2])

