class Node(object):
    def __init__(self, name=None, length=None):
        self.name = name
        self.length = length
        self.descendants = []
        self.ancestor = None

    def remove_internal_names(self):
        for n in self.walk():
            if not n.is_leaf:
                n.name = None

    @property
    def is_leaf(self):
        return not bool(self.descendants)

    def walk(self):
        yield self
        for node in self.descendants:
            for n in node.walk():
                yield n

def test_remove_internal_names():
    # Create the test tree structure
    root = Node("root")
    internal_node = Node("internal")
    leaf1 = Node("leaf1")
    leaf2 = Node("leaf2")

    root.descendants = [internal_node]
    internal_node.ancestor = root
    internal_node.descendants = [leaf1, leaf2]
    leaf1.ancestor = internal_node
    leaf2.ancestor = internal_node

    # Check names before removing internal names
    assert internal_node.name == "internal"
    assert leaf1.name == "leaf1"

    # Remove internal names
    root.remove_internal_names()

    # Check names after removing internal names
    assert root.name is None, "The root node's name should be None after removal."
    assert internal_node.name is None, "The internal node's name should be None after removal."
    assert leaf1.name == "leaf1", "The leaf node's name should remain unchanged."
    assert leaf2.name == "leaf2", "The leaf node's name should remain unchanged."

