from typing import Generic, Sequence, TypeVar

Input = TypeVar('Input')

class Reader(Generic[Input]):
    """Abstract base class for readers."""

    first = NotImplemented  # type: Input
    rest = NotImplemented  # type: Reader[Input]
    position = NotImplemented  # type: int
    finished = NotImplemented  # type: bool

    def expected_error(self, expected: str) -> str:
        """Generate a basic error to include the current state."""
        if self.finished:
            return 'Expected {} but found end of source'.format(expected)
        else:
            return 'Expected {} but found {} at index {}'.format(expected, self.first, self.position)

class StringReader(Reader[str]):
    """A reader for strings."""
    def __init__(self, source: str, position: int = 0):
        self.source = source
        self.position = position

    @property
    def first(self) -> str:
        if self.finished:
            return ''  # Return empty string if finished
        return self.source[self.position]

    @property
    def rest(self) -> 'StringReader[str]':
        return StringReader(self.source, self.position + 1)

    @property
    def finished(self) -> bool:
        return self.position >= len(self.source)

def test_expected_error():
    reader = StringReader("Hello")
    # Expect the correct 'H' at the start of the source, error message should be formatted with the 'H' and index 0
    assert reader.expected_error("H") == 'Expected H but found H at index 0'

    # Expect a 'W', which is not at the start, error includes 'H' at index 0
    assert reader.expected_error("W") == 'Expected W but found H at index 0'

    # Test the finished reader, should output error for end of source
    finished_reader = StringReader("Hello", position=5)
    assert finished_reader.expected_error("anything") == 'Expected anything but found end of source'

if __name__ == '__main__':
    test_expected_error()
    print("All tests passed!")

