class Exon:
    def __init__(self, exon_id, chrom, start, end, rank, transcript, hgnc_id, build):
        self.exon_id = exon_id
        self.chrom = chrom
        self.start = start
        self.end = end
        self.rank = rank
        self.transcript = transcript
        self.hgnc_id = hgnc_id
        self.build = build


def build_exon(exon_info, build='37'):
    try:
        chrom = exon_info['chrom']
    except KeyError:
        raise KeyError("Exons has to have a chromosome")

    try:
        if not isinstance(exon_info['start'], int):
            raise TypeError("Exon start has to be integer")
        start = exon_info['start']
    except KeyError:
        raise KeyError("Exon has to have a start")

    try:
        if not isinstance(exon_info['end'], int):
            raise TypeError("Exon end has to be integer")
        end = exon_info['end']
    except KeyError:
        raise KeyError("Exon has to have a end")

    try:
        if not isinstance(exon_info['rank'], int):
            raise TypeError("Exon rank has to be integer")
        rank = exon_info['rank']
    except KeyError:
        raise KeyError("Exon has to have a rank")

    try:
        exon_id = exon_info['exon_id']
    except KeyError:
        raise KeyError("Exons has to have a id")

    try:
        transcript = exon_info['transcript']
    except KeyError:
        raise KeyError("Exons has to have a transcript")

    try:
        if not isinstance(exon_info['hgnc_id'], int):
            raise TypeError("hgnc_id has to be integer")
        hgnc_id = exon_info['hgnc_id']
    except KeyError:
        raise KeyError("Exons has to have a hgnc_id")

    exon_obj = Exon(
        exon_id=exon_id,
        chrom=chrom,
        start=start,
        end=end,
        rank=rank,
        transcript=transcript,
        hgnc_id=hgnc_id,
        build=build,
    )

    return exon_obj


def test_build_exon():
    exon_info_correct = {
        "exon_id": "1-123-456",
        "chrom": "1",
        "start": 123,
        "end": 456,
        "transcript": "ENST1",
        "hgnc_id": 1,
        "rank": 1
    }
    exon_obj = build_exon(exon_info_correct)
    assert exon_obj.exon_id == "1-123-456"
    assert exon_obj.chrom == "1"
    assert exon_obj.start == 123
    assert exon_obj.end == 456
    assert exon_obj.transcript == "ENST1"
    assert exon_obj.hgnc_id == 1
    assert exon_obj.rank == 1
    assert exon_obj.build == '37'

    exon_info_missing_start = {
        "exon_id": "1-123-456",
        "chrom": "1",
        "end": 456,
        "transcript": "ENST1",
        "hgnc_id": 1,
        "rank": 1
    }
    try:
        build_exon(exon_info_missing_start)
        assert False, "KeyError exception should have been raised"
    except KeyError as e:
        assert str(e) == "'Exon has to have a start'"

    exon_info_incorrect_start = {
        "exon_id": "1-123-456",
        "chrom": "1",
        "start": "123",
        "end": 456,
        "transcript": "ENST1",
        "hgnc_id": 1,
        "rank": 1
    }
    try:
        build_exon(exon_info_incorrect_start)
        assert False, "TypeError exception should have been raised"
    except TypeError as e:
        assert str(e) == "Exon start has to be integer"


if __name__ == '__main__':
    test_build_exon()

