    api_client = ApiClientMock()
    client = Client(api_client)

    # Test getting the parent of a sub-folder in folder1
    assert client.get_parent("/folder1/subfolder1") == {"uuid": "folder1_uuid", "entity_type": "folder"}, "Failed to retrieve parent of /folder1/subfolder1"

    # Test getting the parent of a top-level folder
    assert client.get_parent("/folder2") == {"uuid": "root_uuid", "entity_type": "folder"}, "Failed to retrieve parent of /folder2"

    # Test exception when trying to get parent of root, which is not allowed in this case
