        client.get_parent("/")
        assert False, "Exception was not raised for getting parent of root /"
    except Exception as e:
        assert str(e) == "This method does not accept projects in the path.", "Incorrect exception message for getting parent of root /"

if __name__ == '__main__':
    test_get_parent()

