class MetricCreateBulk(MetricCommon):

    def __init__(self):
        super().__init__()
        self.metrics = None
        self.file_path = None
        self.v2Metrics = None

    def add_arguments(self, file_path):
        self.file_path = file_path

    def load_and_parse(self):
        f = open(self.file_path, "r")
        metrics_json = f.read()
        self.metrics = json.loads(metrics_json)

    def import_metrics(self):
        self.v2Metrics = self.metricDefinitionV2(self.metrics)
        if self.v2Metrics:
            metrics = self.metrics
        else:
            metrics = self.metrics['result']

        for m in metrics:
            if self.v2Metrics:
                metric = metrics[m]
                metric['name'] = m
            else:
                metric = m
            self.create_update(metric)

    def create_update(self, metric):
        print("Creating/Updating metric: {0}".format(metric['name']))
        self.api_result = {"status_code": 200, "text": json.dumps(metric)}

