    test_axis = (0,)
    mock_context = MockContext()
    cs = ConstructSpark()

    output = cs._wrap(test_func, test_shape, context=mock_context)
    assert isinstance(output, BoltArraySpark)
    assert output.shape == test_shape
    assert output.split == len(test_axis)

    test_axis = (1,)
    output = cs._wrap(test_func, test_shape, context=mock_context, axis=test_axis)
    assert output.split == len(test_axis)

    int_shape = 5
    output = cs._wrap(test_func, int_shape, context=mock_context)
    assert output.shape == (int_shape,)

