import re

class Accounting(object):
    def __init__(self, options={}):
        settings = {
            'currency': {
                'symbol': "$",
                'format': "%s%v",
                'decimal': ".",
                'thousand': ",",
                'precision': 2,
                'grouping': 3
            },
            'number': {
                'precision': 0,
                'grouping': 3,
                'thousand': ",",
                'decimal': "."
            }
        }
        if options:
            settings.update(options)

        self.settings = settings

    def parse(self, value, decimal=None):
        value = value or 0

        if isinstance(value, list):
            return list(map(lambda val: self.parse(val, decimal), value))

        if isinstance(value, int) or isinstance(value, float):
            return value

        decimal = decimal or self.settings['number']['decimal']

        regex = re.compile("[^0-9-" + re.escape(decimal) + "]")
        unformatted = str(value)
        unformatted = re.sub(r'\((.*)\)', r"-\1", unformatted)
        unformatted = re.sub(regex, '', unformatted)

        # First, replace the decimal separator with a dot, then remove the thousand separator
        unformatted = unformatted.replace(decimal, '.').replace(',', '')

        # Check if the formatted number matches a valid float pattern
        pattern = re.compile(r"^-?\d+(\.\d+)?$")
        formatted = unformatted if pattern.match(unformatted) else 0

        return float(formatted)

def test_parse():
    accounting = Accounting()
    assert accounting.parse("$1,234.56") == 1234.56, "Should parse currency and grouping"
    assert accounting.parse("(1.99)") == -1.99, "Should parse negative number in accounting format"
    assert accounting.parse("1,234") == 1234, "Should parse integer number with thousand separators"
    assert accounting.parse("1.234,56", decimal=",") == 1234.56, "Should parse number with a different decimal separator"
    assert accounting.parse("invalid input") == 0, "Should return 0 for invalid inputs"

if __name__ == "__main__":
    test_parse()

