        print('/Producer ' + self._text_to_string(
            'PDFLite, https://github.com/katerina7479'))
        if self.title:
            print('/Title ' + self._text_to_string(self.title))
        if self.subject:
            print('/Subject ' + self._text_to_string(self.subject))
        if self.author:
            print('/Author ' + self._text_to_string(self.author))
        if self.keywords:
            print('/Keywords ' + self._text_to_string(self.keywords))
        if self.creator:
            print('/Creator ' + self._text_to_string(self.creator))
        print('/CreationDate ' + self._text_to_string(
            'D:' + datetime.now().strftime('%Y%m%d%H%M%S')))
        print('>>')

    def _text_to_string(self, text):
        if text:
