# Override Django's Group with a mockup, since we do not use Django's Group directly
class Group:
    def __init__(self, name):
        self.name = name

    def __eq__(self, other):
        if isinstance(other, Group):
            return self.name == other.name
        return False

class Person:
    full_name = ""
    is_admin = True

    def __str__(self):
        return self.full_name or ''

class User(AbstractBaseUser, PermissionsMixin):
    email = ""
    is_active = True
    person = Person()

