from oauthlib import oauth2
from flask import Flask, request

class MockClient:
    def __init__(self, is_confidential, client_id):
        self.is_confidential = is_confidential
        self.client_id = client_id

class MockRequest:
    def __init__(self, client_id, grant_type):
        self.client_id = client_id
        self.grant_type = grant_type

class OAuth2RequestValidator(oauth2.RequestValidator):
    def __init__(self, clientgetter):
        self._clientgetter = clientgetter

    def _get_client_creds_from_request(self, request):
        return request.client_id, None

    def client_authentication_required(self, request, *args, **kwargs):
        def is_confidential(client):
            if hasattr(client, 'is_confidential'):
                return client.is_confidential
            client_type = getattr(client, 'client_type', None)
            if client_type:
                return client_type == 'confidential'
            return True

        grant_types = ('password', 'authorization_code', 'refresh_token')
        client_id, _ = self._get_client_creds_from_request(request)
        if client_id and request.grant_type in grant_types:
            client = self._clientgetter(client_id)
            if client:
                return is_confidential(client)
        return False

def clientgetter(client_id):
    if client_id == "confidential-client":
        return MockClient(True, client_id)
    elif client_id == "public-client":
        return MockClient(False, client_id)

def test_client_authentication_required():
    validator = OAuth2RequestValidator(clientgetter)

    # Test with confidential client and authorization_code grant
    confidential_request = MockRequest("confidential-client", "authorization_code")
    assert validator.client_authentication_required(confidential_request)

    # Test with public client and authorization_code grant
    public_request = MockRequest("public-client", "authorization_code")
    assert not validator.client_authentication_required(public_request)

    # Test with confidential client and an unsupported grant_type
    unsupported_request = MockRequest("confidential-client", "unsupported_grant_type")
    assert not validator.client_authentication_required(unsupported_request)

if __name__ == '__main__':
    test_client_authentication_required()

