from typing import Dict

class CachedBotState:
    """
    Internal cached bot state.
    """
    def __init__(self, state: Dict[str, object] = None) : 
        self._state = state if state is not None else {}
        self._hash = self.compute_hash(self._state)

    @property
    def state(self) -> Dict[str, object]:
        return self._state

    @state.setter
    def state(self, state: Dict[str, object]):
        self._state = state

    @property
    def hash(self) -> str:
        return self._hash

    @hash.setter
    def hash(self, hash: str):
        self._hash = hash

    @property
    def is_changed(self) -> bool:
        return self.hash != self.compute_hash(self._state)

    def compute_hash(self, obj: object) -> str:
        # TODO: Should this be compatible with C# JsonConvert.SerializeObject ?
        return str(obj)


class BotState:
    def __init__(self):
        self._context_service_key = "state_key"

    async def clear_state(self, turn_context: Dict):
        """
        Clears any state currently stored in this state scope.

        :param turn_context: The context object for this turn.
        :return: None
        """
        if turn_context is None:
            raise TypeError('BotState.clear_state(): turn_context cannot be None.')

        #  Explicitly setting the hash will mean IsChanged is always true. And that will force a Save.
        cache_value = CachedBotState()
        cache_value.hash = ''
        turn_context[self._context_service_key] = cache_value

def test_clear_state():
    # Test a successful clear
    context = {"user": "tester"}
    bot_state = BotState()
    bot_state._context_service_key = "test_key"  # Modify the key for testing purpose
    import asyncio
    asyncio.run(bot_state.clear_state(context))
    assert "test_key" in context
    assert isinstance(context["test_key"], CachedBotState)
    assert context["test_key"].is_changed # Since hash is set to '', is_changed should return True.

    # Test the exception when turn_context is None
    caught_exception = False
    try:
        asyncio.run(bot_state.clear_state(None))
    except TypeError as e:
        caught_exception = True
    assert caught_exception

    # Test a case where the context already has a state
    pre_existing_state = {"foo": "bar"}
    context["test_key"] = CachedBotState(pre_existing_state)
    asyncio.run(bot_state.clear_state(context))
    assert context["test_key"].state == {}

if __name__ == '__main__':
    test_clear_state()
    print("All tests passed!")

