import re
import string

def iter_properties(fh, comments=False):
    """
    Incrementally read properties from a Java .properties file.

    Yields tuples of key/value pairs.

    If ``comments`` is `True`, comments will be included with ``COMMENT``
    in place of the key.

    :param fh: a readable file-like object
    :param comments: should include comments (default: False)
    """

    COMMENT = b'COMMENT'
    _escapes = {
        "t": "\t",
        "n": "\n",
        "f": "\f",
        "r": "\r",
    }

    _LINE_PATTERN = re.compile(br"^\s*(?P<body>.*?)(?P<backslashes>\\*)$")

    def unirepl(match):
        byte_string = '\\u' + match.group(2).decode("ascii")
        return byte_string.encode('ascii').decode('unicode_escape').encode('latin1')

    _KEY_TERMINATORS_EXPLICIT = "=:"
    _KEY_TERMINATORS = _KEY_TERMINATORS_EXPLICIT + string.whitespace
    _KEY_TERMINATORS_EXPLICIT_BYTES = bytearray(_KEY_TERMINATORS_EXPLICIT, "ascii")
    _KEY_TERMINATORS_BYTES = bytearray(_KEY_TERMINATORS, "ascii")

    def _unescape(value):

        return re.sub(br"(\\+)u([0-9a-fA-F]{4})", unirepl, value)

    def _split_key_value(line):

        return bytes(key_buf), bytes(value)


    def _property_lines(fp):
        buf = bytearray()
        for line in fp:
            if line.startswith(b'#'):
                if comments:
                    yield COMMENT, line.strip()
                continue
            match = _LINE_PATTERN.match(line)
            if not match:
                continue
            body = match.group("body")[:-1] if match.group("backslashes") else match.group("body")
            split_at = None
            for i, char in enumerate(body):
                if char in _KEY_TERMINATORS_BYTES:
                    if body[i:i+1] in _KEY_TERMINATORS_EXPLICIT_BYTES:
                        split_at = i
                        break
                    if i and body[i-1:i] != b'\\':
                        split_at = i
                        break
            if split_at is not None:
                key_buf, value = body[:split_at], body[split_at+1:]

                if key_buf.endswith(b'\\') and not key_buf.endswith(b'\\\\'):
                    key_buf = key_buf[:-1]
                    value = b'=' + value

                key_buf = key_buf.strip()
                value = value.lstrip()
                if value.startswith((b'=', b':')):
                    value = value[1:].lstrip()
                yield key_buf, value
            else:
                yield body, b''

    for key, value in _property_lines(fh):
        if key != COMMENT:
            key = _unescape(key)
        value = _unescape(value)
        yield key, value


def test_iter_properties():
    sample_properties = b"# This is a comment.\nkey1=value1\nkey2:value2\nkey3 value3\n"
    properties_iterator = iter_properties(sample_properties.splitlines(True), comments=True)
    assert next(properties_iterator) == (b'COMMENT', b'# This is a comment.')
    assert next(properties_iterator) == (b'key1', b'value1')
    assert next(properties_iterator) == (b'key2', b'value2')
    assert next(properties_iterator) == (b'key3', b'value3')

# Test implementation
if __name__ == "__main__":
    test_iter_properties()

