def test_copy_fields_from():
    dtype = np.dtype([("x", np.float32), ("y", np.float32), ("z", np.float32), ("intensity", np.uint16)])
    point_format = PointFormat(dtype)

    # Prepare original and copy data
    num_points = 5
    original_data = np.zeros(num_points, dtype=dtype)
    original_data["x"] = np.arange(num_points)
    original_data["y"] = np.arange(num_points) * 2
    original_data["z"] = np.arange(num_points) * 3
    original_data["intensity"] = 100

    # Correct the operation to work on each individual field
    copy_data = np.zeros(num_points, dtype=dtype)
    for field in dtype.names:
        copy_data[field] = original_data[field] * 5

    point_record_original = PointRecord(original_data, point_format)
    point_record_copy = PointRecord(copy_data, point_format)

    # Perform the copy
    point_record_original.copy_fields_from(point_record_copy)

    # Assertions to check if the fields were copied correctly
    assert np.array_equal(point_record_original["x"], point_record_copy["x"]), "X values did not match after copying"
