import numpy as np

class Pauli:
    """A class representing Pauli Operators."""

    def __init__(self, z=None, x=None):
        z = self._format_input(z)
        x = self._format_input(x)

        if len(z) != len(x):
            raise ValueError("Z and X lengths do not match")

        self._z = z
        self._x = x

    def _format_input(self, input_array):
        if isinstance(input_array, list):
            return np.array(input_array).astype(np.bool_)
        elif isinstance(input_array, np.ndarray):
            return input_array.astype(np.bool_)
        else:
            raise ValueError("Input must be list or ndarray")

    def update_x(self, x, indices=None):
        x = self._format_input(x)
        if indices is None:
            if len(self._x) != len(x):
                raise ValueError("X length does not match existing pauli")
            self._x = x
        else:
            if not isinstance(indices, (list, np.ndarray)):
                indices = [indices]
            for i, idx in enumerate(indices):
                self._x[idx] = x[i]
        return self

    @property
    def x(self):
        return self._x

def test_update_x():
    p = Pauli(z=[False, True, False], x=[True, False, True])

    # Update the entire X array
    updated_p = p.update_x([False, False, False])
    assert np.array_equal(updated_p.x, [False, False, False])

    # Update a single element in the X array
    updated_p = p.update_x([True], indices=[1])
    assert np.array_equal(updated_p.x, [False, True, False])

    # Update multiple specified indices in the X array
    updated_p = p.update_x([True, True], indices=[0, 2])
    assert np.array_equal(updated_p.x, [True, True, True])

    print("All tests for update_x passed")

if __name__ == '__main__':
    test_update_x()

