from typing import Any, Callable, Optional, TypeVar, Generic

T = TypeVar("T")
DispatchFunction = Callable[..., T]
Method = Callable[..., Any]

class MultiFunction(Generic[T]):
    def __init__(
        self, name: str, dispatch: DispatchFunction, default: T
    ) -> None:
        self._name = name
        self._default = default
        self._dispatch = dispatch
        self._methods = {}

    def __call__(self, *args, **kwargs):
        key = self._dispatch(*args, **kwargs)
        method = self.methods.get(key, None) or self.methods.get(self._default, None)
        if method:
            return method(*args, **kwargs)
        raise NotImplementedError

    def add_method(self, key: T, method: Method) -> None:
        self.methods[key] = method

    def get_method(self, key: T) -> Optional[Method]:
        return self.methods.get(key, None) or self.methods.get(self._default, None)

    def __remove_method(self, key: T) -> None:
        if key in self.methods:
            self.methods.pop(key)

    def remove_method(self, key: T) -> Optional[Method]:
        method = self.methods.get(key, None)
        if method:
            self.__remove_method(key)
        return method

    def remove_all_methods(self) -> None:
        self.methods.clear()

    @property
    def default(self) -> T:
        return self._default

    @property
    def methods(self) -> dict:
        return self._methods

