class GeneHandler(object):
    def __init__(self):
        self.mock_db = {}

    def load_hgnc_bulk(self, gene_objs):
        LOG.info("Loading gene bulk with length %s", len(gene_objs))
        if not gene_objs:
            return MockInsertManyResult([], True)

        for gene_obj in gene_objs:
            if gene_obj['_id'] in self.mock_db:
                raise IntegrityError("DuplicateKeyError")
            self.mock_db[gene_obj['_id']] = gene_obj

        inserted_ids = [gene['_id'] for gene in gene_objs]
        return MockInsertManyResult(inserted_ids, True)

def test_load_hgnc_bulk():
    mock_gene_objs = [{'_id': '1', 'symbol': 'GENE1'}, {'_id': '2', 'symbol': 'GENE2'}, {'_id': '3', 'symbol': 'GENE3'}]

    handler = GeneHandler()
    handler.mock_db.clear()  # Ensure the mock database is empty

    result = handler.load_hgnc_bulk(mock_gene_objs)
    assert result.acknowledged == True
    assert result.inserted_ids == ['1', '2', '3']

    try:
        handler.load_hgnc_bulk(mock_gene_objs)
        assert False, "IntegrityError was not raised on duplicate key"
    except IntegrityError:
        assert True

    result_empty = handler.load_hgnc_bulk([])
    assert result_empty.inserted_ids == []

if __name__=='__main__':
    test_load_hgnc_bulk()

