        nmin = self.wprogressbar['nmin']
        nmax = self.wprogressbar['nmax']
        if (nmax - nmin) == 0:
            percent = 0
        else:
            percent = max(min((n - nmin) / (nmax - nmin), 1.), 0.) * 100
        self.wprogresslabel['label'] = self._label_progressbar_fmt.format(n=round(n, 4), nmin=round(nmin, 4), nmax=round(nmax, 4), percent=round(percent, 4))

